-- HALO: apply migrations 0024 to 0033 in one paste.
-- Generated by scripts/build-apply-bundle.mjs from supabase/migrations; do not edit by hand.
-- Needs 0001 to 0023 applied first (they are, on production, since 2026-10-19).
-- One transaction: if any statement fails, nothing is changed (run `rollback;` if the
-- editor says the transaction is aborted), then send the error text. Safe to run twice.
-- Afterwards run verify-0024-to-0033.sql and expect all_migrations_ok = true.

begin;

-- ===========================================================================
-- 0024_privacy_clear.sql
-- ===========================================================================

-- HALO: privacy, the household's own clear of its records, the review
-- fingerprint, the inspect counts, the receipt purge, the status probe and a
-- freeze on settled privacy receipts (B07 plan, Task 1, Rulings P3, P4, P6,
-- P10, P11 and P16).
--
-- Run once in the Supabase SQL editor, AFTER 0023. Safe to re-run. Before the
-- first apply, run the profiles column check in docs/backend/YOUR_TODO.md 2.14
-- against production: it must return no rows.
--
-- Locks: creates six functions and one trigger, and no table. Creating the
-- trigger on public.operations takes a brief SHARE ROW EXCLUSIVE on that
-- table (a re-run replaces it under the same brief lock), so any ledger claim
-- or settle at that moment waits for it. Nothing existing is read or
-- rewritten.
--
-- REFUSES TO APPLY ON A LAGGING SCHEMA (Ruling P11). The first statement
-- checks that every table this file reads or deletes from exists, and that
-- profiles.tenure does (0016, 0017, 0020, 0021, 0022 and 0023), and raises
-- naming what is missing otherwise. So wherever clear_household_records
-- exists, every table it deletes from exists too, with one deliberate
-- exception: public.daily_maxima (0025, B08 Ruling E23) needs only 0016 and
-- may be applied before or after this file, so the clear and the counts
-- check for it with to_regclass and read it only when it is there.
--
-- ---------------------------------------------------------------------------
-- THE FUNCTIONS, FOR THE CALLERS (lib/privacyStore.js, Task 2)
-- ---------------------------------------------------------------------------
-- All six are security invoker with search_path pinned to public, and only
-- service_role may execute them. p_profile_id is always the verified session
-- owner: the routes pass it, never the client.
--
--   public.privacy_schema_version() returns int
--     Immutable, always 1. The status probe: a missing function (PGRST202 or
--     42883) means 0024 is not applied, and privacy answers 503 (P11).
--
--   public.privacy_fingerprint(p_profile_id uuid, p_tables text[]) returns text
--     Stable. 64 lowercase hex characters: SHA-256 over, for each listed table
--     in the fixed order below, the sorted md5 of each of the household's
--     rows as JSON (profiles: the reset columns only; home_contexts: every
--     column but backfill_state, backfill_from, backfill_to and
--     backfill_updated_at). p_tables must be a subset of, with no repeats:
--       profiles, home_contexts, household_bands, symptom_logs,
--       notification_prefs, push_subscriptions, profile_preferences,
--       explore_areas, household_actions, household_action_preferences,
--       luna_conversations, luna_turns
--     in any order (the order passed does not change the result). Anything
--     else is HALO_INVALID_INPUT. An empty array gives one fixed constant.
--     Server-written tables (daily_scores, alerts, home_risks, luna_runs,
--     household_action_state, operations, and daily_maxima where 0025 is
--     applied) are deliberately not fingerprinted (P6), so a background
--     refresh does not void a review. For the same
--     reason home_contexts is hashed without its four backfill_* columns,
--     which the history backfill writes in the background.
--     Luna's answer turns are server-written too, and so are the revision and
--     updated_at of the conversation they advance, but luna_turns and
--     luna_conversations ARE fingerprinted, on purpose: a turn is written
--     only because the person asked a question, and the transcript is what
--     the person reviewed, so a question answered between review and confirm
--     voids the review (the person asks again).
--     The tables clear_household_records checks for each scope:
--       journal  {symptom_logs}
--       all      every table in the list above
--
--   public.privacy_counts(p_profile_id uuid, p_scope text) returns jsonb
--     Stable. What clear_household_records would remove for p_scope, read in
--     one statement, as {<table>: n} with every key present (0 included):
--       journal  {"symptom_logs": n, "alerts": n}   alerts: season summaries only
--       all      {"profiles": 0 or 1, "home_contexts", "daily_scores",
--                 "home_risks", "household_bands", "symptom_logs", "alerts",
--                 "notification_prefs", "push_subscriptions",
--                 "profile_preferences", "explore_areas", "household_actions",
--                 "household_action_preferences", "household_action_state",
--                 "luna_conversations", "luna_turns", "luna_runs",
--                 "operations", "daily_maxima"}
--     daily_maxima is 0 where 0025 is not applied.
--     profiles is 1 when the row holds any value its reset would change.
--     operations counts the household's settled rows (a pending one makes the
--     clear refuse instead). recovery_challenges and auth.users are kept, so
--     they are not counted.
--
--   public.clear_household_records(p_profile_id uuid, p_operation_id uuid,
--                                  p_scope text, p_fingerprint text) returns jsonb
--     The clear, one transaction (P3, P4). p_scope is 'journal' or 'all';
--     p_fingerprint is privacy_fingerprint over that scope's tables, as the
--     review token bound it; p_operation_id is the caller's own pending ledger
--     row, domain 'privacy', kind 'privacy.clear.<scope>'. Returns
--       {"receipt": {"operationId": "<uuid>", "status": "succeeded",
--                    "scope": "journal" | "all"},
--        "removed": <int, total rows deleted plus 1 for a reset profile>}
--     and has already settled the ledger row 'succeeded' with exactly that
--     receipt. `removed` is for tests and logs, never for a response or the
--     ledger.
--
--   public.purge_privacy_receipts(p_profile_id uuid default null) returns int
--     Deletes settled 'privacy' ledger rows whose updated_at is more than 24
--     hours ago: only this owner's when p_profile_id is given, every
--     household's when it is null (the daily cron). Pending rows are never
--     touched (the reaper owns them). A row another transaction has locked
--     (a clear in progress) is skipped, not waited for, and goes on a later
--     run. Returns how many it deleted.
--
--   public.guard_settled_privacy_operation() returns trigger
--     The trigger function of operations_privacy_settled_guard (P16). Not
--     callable.
--
-- Refusals are SQLSTATE P0001 with exactly this message. DETAIL names the
-- argument or the rule, never a row value, an id or a fingerprint (0021
-- review finding B):
--   HALO_INVALID_INPUT          a null argument, a scope other than journal or
--                               all, a fingerprint that is not 64 lowercase hex
--                               characters, or a table outside the list
--   HALO_OPERATION_NOT_PENDING  the ledger row is missing, settled, another
--                               household's, another domain's or another
--                               kind's (all the same error); nothing written
--   HALO_REVIEW_CHANGED         the records moved since the review; nothing written
--   HALO_BUSY                   other work is pending (below); nothing written
--   HALO_OPERATION_SETTLED      the trigger: a settled privacy row's status may
--                               not change
-- Anything else (a deadlock, 40P01, see the lock graph) is Postgres's own
-- error, and it too leaves nothing deleted and the ledger row pending.
--
-- ---------------------------------------------------------------------------
-- THE CLEAR (Rulings P3 and P4, Vibhav's D-P1 and D-P4)
-- ---------------------------------------------------------------------------
-- One function call is one transaction, so every deletion, the profile reset
-- and the settle of the caller's own ledger row commit together or none of
-- them does:
--
--   1. Lock the profile FOR UPDATE. Every insert into an owned table takes FOR
--      KEY SHARE on it for its foreign key, so while the clear runs no new
--      household row, ledger claims included, can be written: they wait.
--   2. Lock this operation's own ledger row, which must be this household's,
--      domain 'privacy', kind 'privacy.clear.<scope>', still 'pending'.
--      Otherwise HALO_OPERATION_NOT_PENDING. The reaper settles an abandoned
--      row with a conditional `update ... where status = 'pending'`, so the
--      two exclude each other (the B06 H8 argument): a reaped row is never
--      cleared, and a clear that holds its row is never reaped.
--   3. Recompute the review fingerprint for the scope and compare it with
--      p_fingerprint, or HALO_REVIEW_CHANGED.
--   4. Refuse with HALO_BUSY while other work is pending. For 'all': any other
--      ledger row of this household that is 'pending', in any domain, or a
--      Luna run 'queued' or 'generating' updated within the last 120 seconds
--      (lib/operations.js DEFAULT_STALE_AFTER_MS; an older one is dead and is
--      cleared with its conversation). For 'journal': another pending
--      'privacy' row. Step 1 means no new claim can appear after this check.
--   5. Delete, every statement scoped to p_profile_id, in foreign-key-safe
--      order. 'journal': symptom_logs, and alerts of type 'season_summary'
--      (D-P4; journal findings are computed on read, so nothing else is
--      derived). 'all': Luna runs, turns, then conversations (what the
--      cascade from the conversation would remove, deleted child first so
--      each is counted); daily_scores before home_contexts (their composite
--      key is ON DELETE NO ACTION, 0016), and daily_maxima before
--      home_contexts too when 0025 is applied (its key cascades, but deleting
--      it first counts it); home_risks, symptom_logs, alerts;
--      notification_prefs, household_bands, push_subscriptions, then
--      profile_preferences (notifications before bands before preferences,
--      the order save_settings and the 0021 triggers take them);
--      explore_areas; household_actions, household_action_preferences,
--      household_action_state; then every settled ledger row of the household
--      except this one.
--   6. 'all' only: reset the profile. The row is NOT deleted: operations
--      cascades from it, so deleting it would delete this clear's own receipt
--      and reconcile would 404, and a login with no profile is a state no
--      route expects (0001's handle_new_user makes it only on sign-up). It
--      keeps id and created_at; every other column goes back to its column
--      default (`= default`), which on the schema as migrated is null for
--      address, lat, lng, zip, county, pwsid, build_year, water_source,
--      home_year, state, onboard_request_id and tenure, false for renter_mode
--      and 'en' for locale. With lat and lng null, GET /api/profile answers
--      onboarded: false. The 0021 triggers run as for any profile write and
--      change nothing: tenure is already null, and the settings revision
--      trigger finds the preferences row already deleted.
--   7. Settle the own ledger row 'succeeded' with the minimal receipt
--      {operationId, status, scope} (P10). No row content, no count.
--   8. Return {receipt, removed}.
--
-- So a deletion exists if and only if its operation is 'succeeded'. Every
-- refusal raises before anything is deleted, and any error after rolls the
-- deletions back with it, so "The request was not applied. Your data is
-- unchanged." is true for every 'failed' (trap P-13).
--
-- KEPT by 'all' (D-P1, P4): the auth.users row (the login), the reset profile
-- row, recovery_challenges (proof material about the login, Open question 2),
-- this clear's own receipt (purged 24 hours after it settles), and any other
-- household's rows, which no statement here can reach.
--
-- ---------------------------------------------------------------------------
-- THE LOCK GRAPH (reasoned on paper: PGlite has one connection)
-- ---------------------------------------------------------------------------
-- Resources for one household: A its auth.users row, P its profile row, O the
-- clear's own ledger row, O' any other ledger row, N notification_prefs, B
-- household_bands, R profile_preferences, C a Luna conversation row, H a home
-- context row, X any other owned row.
--
--   clear_household_records   P (for update) -> O (for update) -> reads, no
--                             locks -> deletes of child rows in the order of
--                             step 5 (X, C, H, N -> B -> R) -> O' (delete) ->
--                             P (update, held) -> O (settle, held). Never A:
--                             the reset changes no key column, so no foreign
--                             key check against auth.users runs.
--   DELETE /api/account       A -> P (delete) -> cascade to O, O', N, B, R, X.
--                             P before O, the same as the clear.
--   save_settings (0021)      P -> O_settings -> N -> B -> R.
--   save_household (0015),    P first.
--   0016 functions
--   commit_household_actions  O_actions -> household_action_state -> task
--   (0023)                    rows -> FOR KEY SHARE on P for each insert.
--   runOperation claim        inserts O_new, then FOR KEY SHARE on P.
--   runOperation settle       one O row by id, nothing else.
--   reaper                    pending O rows only, nothing else.
--   purge_privacy_receipts    settled privacy O' rows only, nothing else, and
--                             FOR UPDATE SKIP LOCKED: it never waits on a row.
--   PUT /api/notifications    N -> R (trigger); an insert also KEY SHARE on P.
--   Luna statements           single statements: a turn or run insert takes
--                             KEY SHARE on C, on its turn and on P.
--   daily cron                single statements: an alert insert KEY SHARE on
--                             P, a reading insert KEY SHARE on P and H.
--   record_daily_maxima       first an advisory lock only it takes (one
--   (0025)                    recorder batch at a time), then per row, KEY
--                             SHARE on P, then on H, then the row. P first,
--                             so it waits on the clear's P and then skips
--                             the deleted home: no cycle.
--
-- Why no cycle forms with the house writers:
--   * account deletion, save_settings, save_household and the 0016 functions
--     all take P first, so each serializes with the clear on P. Account
--     deletion holds only A while it waits, which the clear never wants. If
--     it wins, the clear's ledger row is cascaded away and the clear raises
--     HALO_OPERATION_NOT_PENDING.
--   * commit_household_actions holds O_actions and task rows and then waits
--     on P. Its O_actions row was claimed, and committed as 'pending', by an
--     earlier statement, so a clear 'all' that holds P reads it at step 4 and
--     raises HALO_BUSY before it touches any task row; a clear 'journal'
--     never touches task rows. Either way the clear never waits on the
--     commit, the commit waits on the clear, and there is no cycle. (This
--     closes, for this pairing, the deadlock the plan's finding F3 allowed.)
--   * a ledger claim inserts O_new and then waits on P. The clear does not
--     see the uncommitted row, so it neither waits on it nor counts it busy;
--     the claim goes on after the clear commits (plan finding F2: a new,
--     deliberate request).
--   * the reaper and runOperation's settle hold O rows only and never wait on
--     P. If the reaper holds O, the clear waits, then finds O no longer
--     pending and refuses. Neither wants anything the clear holds.
--   * PUT /api/notifications takes N then R, and the clear deletes N before R,
--     the same order, so they wait rather than deadlock.
--   * purge_privacy_receipts selects its rows FOR UPDATE SKIP LOCKED, so it
--     skips every settled row the clear has deleted and not yet committed
--     (the clear removes them itself) and never waits on the clear. Without
--     SKIP LOCKED the two would delete the same household's settled privacy
--     rows each in its own scan order, and two such rows locked in opposite
--     orders would be a cycle.
--   * Luna and cron inserts (a turn or run insert: P and C; a reading insert:
--     P and H). An insert checks each of its foreign keys with an RI trigger,
--     and Postgres fires a table's triggers in name order. The RI triggers
--     are named RI_ConstraintTrigger_c_<trigger oid>, and on this schema the
--     profiles key's trigger sorts first on luna_turns, luna_runs and
--     daily_scores (it was created first, so its number is lower; the
--     ordering is pinned by test/privacyClearDb.test.mjs). So the insert
--     asks for KEY SHARE on P first, while it holds nothing but its own
--     uncommitted tuple, which the clear's deletes cannot see. It waits on P;
--     when the clear commits, the P check passes and the C or H check fails
--     with 23503 (the row is gone). The insert is refused, the clear is
--     whole, and no cycle forms.
-- Residual, accepted: the same Luna and cron inserts deadlock with the clear
-- only where the profiles key's trigger would sort AFTER the C or H key's.
-- That needs a production database whose trigger names sort differently from
-- PGlite's: the constraint oids straddling a change in digit count (for
-- example c_99999 before c_100000 compares as text the other way round), or
-- a constraint dropped and re-created after the other so its oid is higher.
-- Then the insert would hold KEY SHARE on C or H and wait on P while the clear
-- held P and waited on C or H; one side dies with 40P01. That is still
-- honest: a 40P01 on the clear rolls it back whole and leaves its row pending
-- (so 'failed' is true), and an aborted insert loses only its own write. No
-- cheap reordering helps: locking C and H before P would invert against the
-- P-first 0016 functions, and weakening the P lock to FOR NO KEY UPDATE would
-- let an insert land behind the deletes and survive a 'succeeded' clear.
--
-- ---------------------------------------------------------------------------
-- RETENTION AND PRIVACY
-- ---------------------------------------------------------------------------
-- No table is created, so nothing new is retained. Privacy receipts are
-- ordinary 0017 ledger rows in domain 'privacy' holding {operationId, status,
-- scope} (and an export's group names and private-text choice), and
-- purge_privacy_receipts removes them 24 hours after they settle (Ruling P10,
-- Open question 1). The fingerprint never leaves the server and is never
-- stored.
--
-- Degrades cleanly: until this is applied, privacy.status reports the
-- feature unavailable from its probe (P11), and nothing else calls these
-- functions.

-- ---------------------------------------------------------------------------
-- 1. Refuse to apply on a lagging schema (Ruling P11)
-- ---------------------------------------------------------------------------

do $$
declare
  missing text;
begin
  select string_agg(format('%s (%s)', t.name, t.migration), ', ' order by t.at) into missing
    from (values
      (1, 'public.home_contexts', '0016'),
      (2, 'public.operations', '0017'),
      (3, 'public.luna_conversations', '0020'),
      (4, 'public.luna_turns', '0020'),
      (5, 'public.luna_runs', '0020'),
      (6, 'public.profile_preferences', '0021'),
      (7, 'public.explore_areas', '0022'),
      (8, 'public.household_actions', '0023'),
      (9, 'public.household_action_preferences', '0023'),
      (10, 'public.household_action_state', '0023')
    ) as t(at, name, migration)
   where to_regclass(t.name) is null;
  if not exists (
    select 1 from information_schema.columns
     where table_schema = 'public' and table_name = 'profiles' and column_name = 'tenure'
  ) then
    missing := concat_ws(', ', missing, 'public.profiles.tenure (0021)');
  end if;
  if missing is not null then
    raise exception 'HALO 0024 cannot be applied: missing %. Apply 0016 to 0023 first.', missing;
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 2. privacy_schema_version: the status probe (Ruling P11)
-- ---------------------------------------------------------------------------

create or replace function public.privacy_schema_version()
returns int
language sql
immutable
security invoker
set search_path = public
as $$
  select 1;
$$;

revoke execute on function public.privacy_schema_version() from public, anon, authenticated;
grant execute on function public.privacy_schema_version() to service_role;

-- ---------------------------------------------------------------------------
-- 3. privacy_fingerprint: what a review binds (Ruling P6)
-- ---------------------------------------------------------------------------
-- The JSON text of a row depends on two session settings: TimeZone (the
-- offset a timestamptz is written with) and extra_float_digits (how a double
-- precision is written). Both are pinned on the function, so a review minted
-- through one PostgREST session verifies through another. Hashes are sorted
-- byte-wise (collate "C"), so the result does not depend on the database's
-- collation or on the order rows were inserted in.

create or replace function public.privacy_fingerprint(p_profile_id uuid, p_tables text[])
returns text
language plpgsql
stable
security invoker
set search_path = public
set timezone to 'UTC'
set extra_float_digits to 1
as $$
declare
  -- The fixed order, and the whole of what may be fingerprinted.
  fingerprint_tables constant text[] := array[
    'profiles', 'home_contexts', 'household_bands', 'symptom_logs', 'notification_prefs',
    'push_subscriptions', 'profile_preferences', 'explore_areas', 'household_actions',
    'household_action_preferences', 'luna_conversations', 'luna_turns'
  ];
  material  text := 'halo:privacy-fingerprint:v1';
  tbl       text;
  part      text;
begin
  if p_profile_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id is required';
  end if;
  if p_tables is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_tables is required';
  end if;
  if array_position(p_tables, null) is not null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_tables may not contain null';
  end if;
  if exists (select 1 from unnest(p_tables) t where t <> all (fingerprint_tables)) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001',
      detail = 'p_tables names a table the privacy fingerprint does not cover';
  end if;
  if exists (select 1 from unnest(p_tables) t group by t having count(*) > 1) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_tables names a table more than once';
  end if;

  foreach tbl in array fingerprint_tables loop
    continue when not (tbl = any (p_tables));
    if tbl = 'profiles' then
      -- The reset columns only: id is the owner and created_at never changes.
      select coalesce(string_agg(s.h, ',' order by s.h collate "C"), '') into part
        from (select md5(row_to_json(r)::text) as h
                from (select p.address, p.lat, p.lng, p.zip, p.county, p.pwsid, p.build_year,
                             p.water_source, p.home_year, p.renter_mode, p.locale, p.state,
                             p.onboard_request_id, p.tenure
                        from public.profiles p where p.id = p_profile_id) r) s;
    elsif tbl = 'home_contexts' then
      -- Every column but the four backfill_* columns, which the server's
      -- history backfill writes after onboarding or a move
      -- (lib/homeContextRpc.js writeBackfillState). They change neither what
      -- a clear removes nor what the person reviewed, so a backfill between
      -- review and confirm does not void the review. revision and updated_at
      -- stay: they move only on the person's own answers.
      select coalesce(string_agg(s.h, ',' order by s.h collate "C"), '') into part
        from (select md5(row_to_json(r)::text) as h
                from (select c.id, c.profile_id, c.sequence, c.revision, c.origin, c.lat, c.lng,
                             c.county, c.state, c.pwsid, c.service_area_status, c.water_source,
                             c.home_year, c.match_method, c.onboard_request_id, c.effective_from,
                             c.effective_to, c.closed_reason, c.created_at, c.updated_at
                        from public.home_contexts c where c.profile_id = p_profile_id) r) s;
    else
      -- tbl is one of the constants above, never caller text.
      execute format(
        'select coalesce(string_agg(s.h, '','' order by s.h collate "C"), '''')
           from (select md5(row_to_json(t)::text) as h from public.%I t where t.profile_id = $1) s',
        tbl)
        into part using p_profile_id;
    end if;
    material := material || E'\n' || tbl || ':' || part;
  end loop;

  return encode(sha256(convert_to(material, 'UTF8')), 'hex');
end;
$$;

revoke execute on function public.privacy_fingerprint(uuid, text[]) from public, anon, authenticated;
grant execute on function public.privacy_fingerprint(uuid, text[]) to service_role;

-- ---------------------------------------------------------------------------
-- 4. privacy_counts: what a clear would remove, for inspect's count
-- ---------------------------------------------------------------------------

create or replace function public.privacy_counts(p_profile_id uuid, p_scope text)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
declare
  maxima bigint := 0;
begin
  if p_profile_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id is required';
  end if;
  if p_scope is null or p_scope not in ('journal', 'all') then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_scope must be journal or all';
  end if;

  if p_scope = 'journal' then
    return jsonb_build_object(
      'symptom_logs', (select count(*) from public.symptom_logs x where x.profile_id = p_profile_id),
      'alerts', (select count(*) from public.alerts x where x.profile_id = p_profile_id and x.type = 'season_summary')
    );
  end if;

  -- 0025 may not be applied (header). A stable function reads every
  -- statement from one snapshot, so this is the same read as the rest.
  if to_regclass('public.daily_maxima') is not null then
    select count(*) into maxima from public.daily_maxima x where x.profile_id = p_profile_id;
  end if;

  return jsonb_build_object(
    -- The same test the clear's reset uses (section 5, step 6).
    'profiles', (select count(*) from public.profiles p
                  where p.id = p_profile_id
                    and (num_nonnulls(p.address, p.lat, p.lng, p.zip, p.county, p.pwsid, p.build_year,
                                      p.water_source, p.home_year, p.state, p.onboard_request_id, p.tenure) > 0
                         or p.renter_mode is distinct from false
                         or p.locale is distinct from 'en')),
    'home_contexts', (select count(*) from public.home_contexts x where x.profile_id = p_profile_id),
    'daily_scores', (select count(*) from public.daily_scores x where x.profile_id = p_profile_id),
    'home_risks', (select count(*) from public.home_risks x where x.profile_id = p_profile_id),
    'household_bands', (select count(*) from public.household_bands x where x.profile_id = p_profile_id),
    'symptom_logs', (select count(*) from public.symptom_logs x where x.profile_id = p_profile_id),
    'alerts', (select count(*) from public.alerts x where x.profile_id = p_profile_id),
    'notification_prefs', (select count(*) from public.notification_prefs x where x.profile_id = p_profile_id),
    'push_subscriptions', (select count(*) from public.push_subscriptions x where x.profile_id = p_profile_id),
    'profile_preferences', (select count(*) from public.profile_preferences x where x.profile_id = p_profile_id),
    'explore_areas', (select count(*) from public.explore_areas x where x.profile_id = p_profile_id),
    'household_actions', (select count(*) from public.household_actions x where x.profile_id = p_profile_id),
    'household_action_preferences', (select count(*) from public.household_action_preferences x where x.profile_id = p_profile_id),
    'household_action_state', (select count(*) from public.household_action_state x where x.profile_id = p_profile_id),
    'luna_conversations', (select count(*) from public.luna_conversations x where x.profile_id = p_profile_id),
    'luna_turns', (select count(*) from public.luna_turns x where x.profile_id = p_profile_id),
    'luna_runs', (select count(*) from public.luna_runs x where x.profile_id = p_profile_id),
    'operations', (select count(*) from public.operations x where x.profile_id = p_profile_id and x.status <> 'pending'),
    'daily_maxima', maxima
  );
end;
$$;

revoke execute on function public.privacy_counts(uuid, text) from public, anon, authenticated;
grant execute on function public.privacy_counts(uuid, text) to service_role;

-- ---------------------------------------------------------------------------
-- 5. clear_household_records: the atomic clear (Rulings P3 and P4)
-- ---------------------------------------------------------------------------
-- The steps and the lock graph are in the header.

create or replace function public.clear_household_records(
  p_profile_id    uuid,
  p_operation_id  uuid,
  p_scope         text,
  p_fingerprint   text
)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  journal_tables constant text[] := array['symptom_logs'];
  all_tables     constant text[] := array[
    'profiles', 'home_contexts', 'household_bands', 'symptom_logs', 'notification_prefs',
    'push_subscriptions', 'profile_preferences', 'explore_areas', 'household_actions',
    'household_action_preferences', 'luna_conversations', 'luna_turns'
  ];
  removed  bigint := 0;
  touched  bigint;
  receipt  jsonb;
begin
  -- Arguments first: nothing is read or written for a malformed call.
  if p_profile_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id is required';
  end if;
  if p_operation_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_operation_id is required';
  end if;
  if p_scope is null or p_scope not in ('journal', 'all') then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_scope must be journal or all';
  end if;
  if p_fingerprint is null or p_fingerprint !~ '^[0-9a-f]{64}$' then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001',
      detail = 'p_fingerprint must be 64 lowercase hexadecimal characters';
  end if;

  -- 1. The profile, first, as every writer of this household takes it. A
  --    missing profile is not an error of its own: its ledger rows cascaded
  --    with it, so step 2 refuses.
  perform 1 from public.profiles p where p.id = p_profile_id for update;

  -- 2. This operation's own ledger row, locked under the same condition the
  --    reaper updates it under.
  perform 1 from public.operations o
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'privacy' and o.kind = 'privacy.clear.' || p_scope
     and o.status = 'pending'
     for update;
  if not found then
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;

  -- 3. The records are still the ones the person reviewed.
  if public.privacy_fingerprint(p_profile_id, case when p_scope = 'journal' then journal_tables else all_tables end)
     is distinct from p_fingerprint then
    raise exception 'HALO_REVIEW_CHANGED' using errcode = 'P0001',
      detail = 'the household records changed since the review';
  end if;

  -- 4. Nothing else in flight.
  if p_scope = 'all' then
    if exists (select 1 from public.operations o
                where o.profile_id = p_profile_id and o.operation_id <> p_operation_id
                  and o.status = 'pending') then
      raise exception 'HALO_BUSY' using errcode = 'P0001', detail = 'another operation of this household is pending';
    end if;
    if exists (select 1 from public.luna_runs r
                where r.profile_id = p_profile_id and r.status in ('queued', 'generating')
                  and r.updated_at > now() - interval '120 seconds') then
      raise exception 'HALO_BUSY' using errcode = 'P0001', detail = 'a Luna answer is being written';
    end if;
  else
    if exists (select 1 from public.operations o
                where o.profile_id = p_profile_id and o.operation_id <> p_operation_id
                  and o.domain = 'privacy' and o.status = 'pending') then
      raise exception 'HALO_BUSY' using errcode = 'P0001', detail = 'another privacy request of this household is pending';
    end if;
  end if;

  -- 5. Delete.
  if p_scope = 'journal' then
    delete from public.symptom_logs x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.alerts x where x.profile_id = p_profile_id and x.type = 'season_summary';
    get diagnostics touched = row_count; removed := removed + touched;
  else
    delete from public.luna_runs x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.luna_turns x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.luna_conversations x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    -- Before home_contexts: (profile_id, home_context_id) is ON DELETE NO ACTION.
    delete from public.daily_scores x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    -- 0025, when applied: its key cascades from home_contexts, but deleting
    -- it here first counts it, as privacy_counts does.
    if to_regclass('public.daily_maxima') is not null then
      delete from public.daily_maxima x where x.profile_id = p_profile_id;
      get diagnostics touched = row_count; removed := removed + touched;
    end if;
    delete from public.home_contexts x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.home_risks x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.symptom_logs x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.alerts x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    -- Notifications, then bands, then preferences: the 0021 order.
    delete from public.notification_prefs x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.household_bands x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.push_subscriptions x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.profile_preferences x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.explore_areas x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.household_actions x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.household_action_preferences x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    delete from public.household_action_state x where x.profile_id = p_profile_id;
    get diagnostics touched = row_count; removed := removed + touched;
    -- Every settled ledger row but this one. Step 4 proved none other is
    -- pending; the filter keeps that true by construction.
    delete from public.operations o
     where o.profile_id = p_profile_id and o.operation_id <> p_operation_id and o.status <> 'pending';
    get diagnostics touched = row_count; removed := removed + touched;

    -- 6. Reset the profile: every column but id and created_at to its default.
    --    test/privacyClearDb.test.mjs fails when profiles gains a column this
    --    list does not name.
    update public.profiles p
       set address = default, lat = default, lng = default, zip = default, county = default,
           pwsid = default, build_year = default, water_source = default, home_year = default,
           renter_mode = default, locale = default, state = default,
           onboard_request_id = default, tenure = default
     where p.id = p_profile_id
       and (num_nonnulls(p.address, p.lat, p.lng, p.zip, p.county, p.pwsid, p.build_year,
                         p.water_source, p.home_year, p.state, p.onboard_request_id, p.tenure) > 0
            or p.renter_mode is distinct from false
            or p.locale is distinct from 'en');
    get diagnostics touched = row_count; removed := removed + touched;
  end if;

  -- 7. Settle this operation's own row, in this transaction: the minimal
  --    receipt, no content and no count (Ruling P10).
  receipt := jsonb_build_object('operationId', p_operation_id, 'status', 'succeeded', 'scope', p_scope);
  update public.operations o
     set status = 'succeeded', result = receipt, updated_at = now()
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'privacy' and o.status = 'pending';
  get diagnostics touched = row_count;
  if touched <> 1 then
    -- Cannot happen while step 2's lock is held; kept so the settle is never
    -- assumed.
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;

  -- 8.
  return jsonb_build_object('receipt', receipt, 'removed', removed);
end;
$$;

revoke execute on function public.clear_household_records(uuid, uuid, text, text) from public, anon, authenticated;
grant execute on function public.clear_household_records(uuid, uuid, text, text) to service_role;

-- ---------------------------------------------------------------------------
-- 6. purge_privacy_receipts: settled receipts go after 24 hours (Ruling P10)
-- ---------------------------------------------------------------------------

create or replace function public.purge_privacy_receipts(p_profile_id uuid default null)
returns int
language plpgsql
security invoker
set search_path = public
as $$
declare
  purged int;
begin
  -- SKIP LOCKED: a row another transaction holds is left for the next run.
  -- The one such holder that matters is a clear 'all' deleting the same
  -- household's settled rows (step 5), which removes them itself when it
  -- commits. Without it, the clear and the purge could lock two of those rows
  -- in opposite orders and one of them would die with 40P01; with it, the
  -- purge never waits on a row, so no cycle can form through it.
  delete from public.operations o
   where o.operation_id in (
     select x.operation_id from public.operations x
      where x.domain = 'privacy' and x.status <> 'pending'
        and x.updated_at < now() - interval '24 hours'
        and (p_profile_id is null or x.profile_id = p_profile_id)
        for update skip locked);
  get diagnostics purged = row_count;
  return purged;
end;
$$;

revoke execute on function public.purge_privacy_receipts(uuid) from public, anon, authenticated;
grant execute on function public.purge_privacy_receipts(uuid) to service_role;

-- ---------------------------------------------------------------------------
-- 7. A settled 'privacy' operation keeps its status (Ruling P16)
-- ---------------------------------------------------------------------------
-- runOperation (lib/operations.js) settles by operation id alone and settles
-- 'failed' whenever its execute throws. A clear that committed and then lost
-- its answer on the way back would be turned from 'succeeded' into 'failed',
-- and the person told "Your data is unchanged." after everything was
-- deleted. So, in the 'privacy' domain only, a row that has left 'pending'
-- may not change its status: that settle fails, lib/operations.js logs it,
-- and the row keeps telling the truth. Rewriting a 'succeeded' receipt as
-- 'succeeded' (runOperation adding operationId) is allowed; the reaper only
-- touches 'pending' rows; purge_privacy_receipts deletes, which this does not
-- govern. The 0021 and 0023 guards are the same rule for their own domains.

create or replace function public.guard_settled_privacy_operation()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  raise exception 'HALO_OPERATION_SETTLED' using errcode = 'P0001',
    detail = format('a settled privacy operation keeps its status (%s)', old.status);
end;
$$;

revoke execute on function public.guard_settled_privacy_operation() from public, anon, authenticated;

create or replace trigger operations_privacy_settled_guard
  before update on public.operations
  for each row
  when (old.domain = 'privacy' and old.status <> 'pending' and new.status is distinct from old.status)
  execute function public.guard_settled_privacy_operation();

-- ---------------------------------------------------------------------------
-- Verification (read only). Expect one row, all five columns true.
-- ---------------------------------------------------------------------------
--   select
--     not exists (
--       select 1 from unnest(array['anon', 'authenticated']) as r
--        cross join unnest(array['public.privacy_schema_version()', 'public.privacy_fingerprint(uuid, text[])',
--                                'public.privacy_counts(uuid, text)',
--                                'public.clear_household_records(uuid, uuid, text, text)',
--                                'public.purge_privacy_receipts(uuid)',
--                                'public.guard_settled_privacy_operation()']) as f
--        where has_function_privilege(r, f, 'EXECUTE'))
--       and (select bool_and(has_function_privilege('service_role', f, 'EXECUTE'))
--              from unnest(array['public.privacy_schema_version()', 'public.privacy_fingerprint(uuid, text[])',
--                                'public.privacy_counts(uuid, text)',
--                                'public.clear_household_records(uuid, uuid, text, text)',
--                                'public.purge_privacy_receipts(uuid)']) as f)
--       as functions_service_role_only,
--     (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
--       where n.nspname = 'public' and not p.prosecdef and 'search_path=public' = any (p.proconfig)
--         and p.proname in ('privacy_schema_version', 'privacy_fingerprint', 'privacy_counts',
--                           'clear_household_records', 'purge_privacy_receipts',
--                           'guard_settled_privacy_operation')) = 6
--       as functions_invoker_pinned,
--     exists (select 1 from pg_trigger
--       where tgrelid = 'public.operations'::regclass and tgname = 'operations_privacy_settled_guard')
--       as settled_guard_on,
--     public.privacy_schema_version() = 1 as probe_answers,
--     not exists (
--       select 1 from information_schema.columns
--        where table_schema = 'public' and table_name = 'profiles'
--          and column_name not in ('id', 'created_at', 'address', 'lat', 'lng', 'zip', 'county',
--                                  'pwsid', 'build_year', 'water_source', 'home_year', 'renter_mode',
--                                  'locale', 'state', 'onboard_request_id', 'tenure'))
--       as profiles_reset_complete;
--
-- ---------------------------------------------------------------------------
-- If you need to back out 0024
-- ---------------------------------------------------------------------------
-- The privacy routes go back to answering a non-retryable 503
-- feature_unavailable from their probe, exactly as before this is applied, so
-- backing out disables privacy requests rather than breaking the existing
-- app. Nothing is lost: no table or row is dropped. Privacy receipts already
-- in public.operations stay, and with the guard gone they are ordinary ledger
-- rows again, no longer purged after 24 hours until 0024 is applied again.
-- Nothing else calls these functions, and 0023 is untouched.
--
-- The tested copy of this block is in docs/backend/YOUR_TODO.md, which is what
-- test/migrationBackout.test.mjs runs.
--
-- <!-- backout-0024 -->
-- drop trigger if exists operations_privacy_settled_guard on public.operations;
-- drop function if exists public.guard_settled_privacy_operation();
-- drop function if exists public.purge_privacy_receipts(uuid);
-- drop function if exists public.clear_household_records(uuid, uuid, text, text);
-- drop function if exists public.privacy_counts(uuid, text);
-- drop function if exists public.privacy_fingerprint(uuid, text[]);
-- drop function if exists public.privacy_schema_version();
--
-- Then run: notify pgrst, 'reload schema';

-- ===========================================================================
-- 0025_daily_maxima.sql
-- ===========================================================================

-- HALO: each day's recorded maximum per home, the recorder's one-row state,
-- the write function with its finality rule, and the status probe (B08 plan,
-- docs/backend/plans/b08-evidence.md, Task 1, Rulings E1 to E4, E8 to E10,
-- E16, E22 and E23; Vibhav's decisions of 2026-10-19).
--
-- Run once in the Supabase SQL editor, AFTER 0016. Safe to re-run. It needs
-- nothing newer than 0016: it may be applied before or after 0024, and 0024's
-- clear removes these rows either way (see DELETION below).
--
-- Locks: creates two new tables, one index, five functions and one trigger on
-- the new table, which nothing can be waiting on. The two foreign keys take a
-- brief SHARE ROW EXCLUSIVE on public.profiles and public.home_contexts as
-- they are created, so an onboarding save or a new anonymous sign-up could
-- wait a moment. Nothing existing is read or rewritten.
--
-- REFUSES TO APPLY ON A LAGGING SCHEMA. The first statement checks that
-- public.home_contexts (0016) exists and raises naming it otherwise, so the
-- composite link below can never be created half way.
--
-- ---------------------------------------------------------------------------
-- WHAT THIS IS FOR
-- ---------------------------------------------------------------------------
-- The Patterns and Season screens compare check-ins with the environment, and
-- the client accepts only a series whose basis is 'daily maximum'. Nothing on
-- the server holds one: daily_scores are app-time observations, the moments
-- HALO happened to look, and are never relabelled or copied (E1). From the
-- day the recorder first runs, it fetches each completed day's hourly series
-- and stores here the largest hourly value per home context and factor. Days
-- before that have no daily maximum and are never backfilled (E9).
--
--   public.daily_maxima            one row per home context, local date and
--                                  factor ('air' or 'uv', E7)
--   public.daily_maxima_recorder   one row: recording_from, set once by the
--                                  first run and never moved (E9), and the
--                                  last run's time and counts. No household
--                                  data.
--
-- THE DAY (E2). local_date is the America/New_York calendar date, local
-- midnight to local midnight: 24 hourly slots, 23 on the spring-forward date
-- and 25 on the fall-back date. Every row stores time_zone and
-- hours_expected, and a CHECK pins the zone.
--
-- THE VALUE (E3). The largest hourly value of one source series over the
-- day's slots, computed after the day ended. A value needs at least
-- ceil(0.75 * hours_expected) observed hours (18 of 24, 18 of 23, 19 of 25),
-- held here by a CHECK as the backstop of the recorder's own rule, so one
-- observation is never a maximum (E6). Air is an integer AQI, UV an index.
--
-- MEASURED OR MODELED, NEVER MIXED (E8, E17; Vibhav 2026-10-19). Modeled
-- maxima are allowed under the label and are marked modeled by their
-- source_code. A home never mixes the two in one series: once a home context
-- has a row with a source for a factor and method version, every other row
-- with a source for that home, factor and version must name the same source,
-- or record_daily_maxima refuses that row alone and counts it under the rule
-- source_kind_fixed (the rest of the batch is written). A CHECK pairs
-- each source with its factor, and requires a station code exactly for a
-- measured (AirNow station) row.
--
-- FINAL MEANS FINAL (E4). A row is 'pending' while the recorder may still
-- look at its day. A recorded value, or a final 'source_gap' or
-- 'unavailable', is never rewritten: record_daily_maxima updates only a
-- pending row, and the trigger daily_maxima_final_guard refuses any UPDATE of
-- a row that is not pending, whoever runs it. Deleting is not governed (the
-- person's clear and every cascade delete).
--
-- ---------------------------------------------------------------------------
-- THE FUNCTIONS, FOR THE CALLERS (lib/dailyMaximaStore.js, B08 Task 3)
-- ---------------------------------------------------------------------------
-- All five are security invoker with search_path pinned to public, and only
-- service_role may execute the four that are called.
--
--   public.daily_maxima_schema_version() returns int
--     Immutable, always 1. The probe: a missing function (PGRST202 or 42883)
--     means 0025 is not applied, and the evidence routes answer 503 (E19).
--
--   public.begin_daily_maxima_run(p_first_day date) returns date
--     Writes the recorder's row with recording_from = p_first_day if there is
--     none, and returns the stored recording_from either way. A later call
--     never moves it (E9).
--
--   public.record_daily_maxima(p_rows jsonb) returns jsonb
--     Writes 1 to 1000 rows in one transaction and returns
--       {"inserted": n, "updated": n, "kept": n, "skipped": n,
--        "refused": n, "refusedRules": {"<rule>": n, ...}}
--     Each element of p_rows is an object with exactly these keys (the ones
--     marked ? may be null or absent, the rest are required):
--       profile_id, home_context_id (uuid strings), local_date ('YYYY-MM-DD'),
--       factor, value?, unit, source_code?, station_id?, method_version,
--       time_zone, hours_expected, hours_observed (integers), missing_code?,
--       retrieved_at (a timestamp string)
--     Per row, in this order:
--       refused   the row would break one of the table's CHECKs (tested in
--                 the parse step, before anything is written), or, once its
--                 household is locked, it names a source other than the one
--                 its home already records for that factor and method
--                 version (E8). It is not written, and the rest of the batch
--                 is. refusedRules counts the rule each refused row broke
--                 (the first, in the order below), by name only
--       skipped   the household or its home context no longer exists (deleted
--                 while the run was working), so the row is not written and
--                 the rest of the batch is
--       inserted  no row for (home_context_id, local_date, factor) yet
--       updated   the stored row was 'pending'
--       kept      the stored row is final (a value, 'source_gap' or
--                 'unavailable'), and is left exactly as it was
--     A refused or skipped row writes nothing at all, so one bad row costs
--     only its own day (B08 Task 1 review, finding 1). Every refusal below
--     raises instead and writes nothing of the batch.
--     The rules, one per CHECK on public.daily_maxima (the CHECK stays as the
--     backstop), then the source rule:
--       factor               daily_maxima_factor_check
--       unit_matches_factor  daily_maxima_unit_check
--       value_or_missing     daily_maxima_value_missing_check
--       value_range          daily_maxima_value_range_check
--       air_integer          daily_maxima_air_integer_check
--       missing_code         daily_maxima_missing_code_check
--       source_pairs_factor  daily_maxima_source_check
--       value_needs_source   daily_maxima_value_source_check
--       station_code         daily_maxima_station_check
--       hours_expected       daily_maxima_hours_expected_check
--       hours_observed       daily_maxima_hours_observed_check
--       hours_coverage       daily_maxima_coverage_check
--       method_version       daily_maxima_method_version_check
--       time_zone            daily_maxima_time_zone_check
--       source_kind_fixed    a second source for one home, factor and method
--                            version (E8; Vibhav 2026-10-19, never mixed)
--
--   public.finish_daily_maxima_run(p_counts jsonb) returns timestamptz
--     Records the run's time and counts on the recorder's row and returns the
--     time. p_counts is an object of at most 32 keys whose values are
--     non-negative integers, and it must hold "skipped" and "refused" (the
--     run's totals of the two): counts only, never a coordinate, an id,
--     provider text or a rule name.
--
--   public.guard_final_daily_maximum() returns trigger
--     The trigger function of daily_maxima_final_guard. Not callable.
--
-- Refusals are SQLSTATE P0001 with exactly this message, read by a helper
-- modelled on haloRefusal (lib/homeContextRpc.js). DETAIL names the argument
-- or the rule, never a row value or an id (0021 review finding B):
--   HALO_INVALID_INPUT        a null or malformed argument: p_rows not an
--                             array of 1 to 1000 objects, an unknown or a
--                             missing key, a value of the wrong type, a date
--                             that is not a calendar date, the same home,
--                             date and factor twice in one batch, or a row
--                             naming another household's home context
--   HALO_BEFORE_RECORDING     a row dated before recording_from, or any row
--                             before the first run has begun (E9)
--   HALO_RECORDING_NOT_BEGUN  finish_daily_maxima_run before any begin
--   HALO_DAILY_MAXIMUM_FINAL  the trigger: a row that is not pending may not
--                             be updated (E4)
-- record_daily_maxima never reaches a CHECK, foreign key, not-null or unique
-- violation of its own: every CHECK is tested first and the row refused, the
-- household and home are locked before the write (or the row skipped), every
-- not-null column is a required key, and the insert is ON CONFLICT DO
-- NOTHING. So nothing it raises carries Postgres's own DETAIL, whose
-- "Failing row contains (...)" would name the profile, the home and the
-- values. A direct write to the table by some other service-role statement
-- still meets the CHECKs as Postgres's own 23514, DETAIL included.
--
-- Locks taken by record_daily_maxima. First, before it reads anything, the
-- transaction-scoped advisory lock pg_advisory_xact_lock(800250): the key
-- is this table's own constant (B08, migration 0025), taken by nothing else
-- in HALO, and only by this function. It serializes recorder batches: a
-- second batch (a cron retry, a manual run during the cron) waits for the
-- first to commit, then sees its rows, so two batches can neither deadlock
-- on maxima rows taken in opposite orders nor each record a different
-- source for one home (B08 Task 1 review, finding 3). Being transaction
-- scoped, it is released at the batch's commit or rollback, and is safe
-- through Supabase's transaction pooler. Then, per row: FOR KEY SHARE on the
-- profile, then on the home context, then the row's own insert or update.
-- The profile comes first, as every writer of a household takes it, so a
-- privacy clear (0024), which holds the profile FOR UPDATE and deletes the
-- home context, makes the row wait and then skip it rather than deadlock
-- with it. No other writer takes the advisory lock, so it adds no cycle.
--
-- ---------------------------------------------------------------------------
-- DELETION (E23)
-- ---------------------------------------------------------------------------
-- (profile_id, home_context_id) references home_contexts (profile_id, id) ON
-- DELETE CASCADE, a deliberate difference from daily_scores' NO ACTION
-- (0016), and profile_id references profiles ON DELETE CASCADE. So deleting
-- the account, or deleting a home context, deletes that home's maxima. 0024's
-- clear all deletes this table explicitly, before home_contexts, when it
-- exists, and counts it; without 0024 the cascade alone would remove it.
-- Clear Journal does not touch it. Nothing else deletes a home context.
--
-- Degrades cleanly: until this is applied, the recorder and GET /api/evidence
-- answer a non-retryable 503 feature_unavailable from the probe (E19, a
-- missing function is PGRST202 or 42883, a missing table PGRST205 or 42P01).
-- Nothing else reads these tables. A refused row is not an outage: the
-- batch still commits the rest, the row's day stays without a value, and the
-- recorder reports only refused and refusedRules (counts by rule name, never
-- a row). A recorder batch waiting on another's advisory lock waits at most
-- for that one batch.
--
-- Retention: decided by Vibhav on 2026-10-19. Daily maxima are kept until
-- deleted: the person clears their data (0024's clear all) or deletes the
-- account. No purge job, and none is invented. GET /api/evidence serves the
-- latest 84 days (E14); older rows are kept, not deleted.
--
-- Privacy: dated Air and UV values at a home's stored point, the method, the
-- coverage counts, the AirNow station code for a measured home and when HALO
-- fetched the series. No free text, and no upstream text (an AirNow site name)
-- is stored. The station and the values reveal the home's area, and the dates
-- when the household lived there: classes household_context and
-- location_approximate. The service role is the only reader. Row level
-- security is on with no policy at all and the default privileges are
-- revoked, so not even the owner can read the rows with their own session.
-- Errors: no error the five functions raise carries an id or a row value.
-- Their refusals name the argument or the rule, and record_daily_maxima
-- tests every CHECK before writing, so its ordinary input never meets
-- Postgres's own constraint DETAIL (see the refusals above). Its result
-- names refused rules only by rule name and count. A write to the table
-- outside these functions is the one way left to meet a CHECK's own DETAIL,
-- and only the service role can write.

-- ---------------------------------------------------------------------------
-- 1. Refuse to apply on a lagging schema
-- ---------------------------------------------------------------------------

do $$
begin
  if to_regclass('public.home_contexts') is null then
    raise exception 'HALO 0025 cannot be applied: missing public.home_contexts (0016). Apply 0016 first.';
  end if;
end $$;

-- ---------------------------------------------------------------------------
-- 2. Tables
-- ---------------------------------------------------------------------------

create table if not exists public.daily_maxima (
  -- The owner, so an account deletion cascades.
  profile_id      uuid not null references public.profiles (id) on delete cascade,
  -- The stay the point belongs to (E11). Linked to its owner below.
  home_context_id uuid not null,
  -- The America/New_York calendar date (E2).
  local_date      date not null,
  -- 'air' or 'uv' (E7).
  factor          text not null,
  -- Null exactly when missing_code is set; never 0 for a missing day.
  value           double precision,
  -- 'AQI' for air, 'UV index' for uv.
  unit            text not null,
  -- 'airnow_station' (measured), 'open_meteo_cams' or 'open_meteo_forecast'
  -- (modeled), or null for a row with no source yet (E17).
  source_code     text,
  -- The AirNow AQS code of the nearest station that reported, for an
  -- airnow_station row only (E8).
  station_id      text,
  -- The method version, 'daily-max-v1' (E10).
  method_version  text not null,
  -- 'America/New_York' (E2).
  time_zone       text not null,
  -- 23, 24 or 25 (E2).
  hours_expected  smallint not null,
  -- The least-covered pollutant's count of hourly values (E3).
  hours_observed  smallint not null,
  -- 'pending', 'source_gap' or 'unavailable' (E4); null for a value.
  missing_code    text,
  -- When HALO fetched the series. Audit only, never emitted (E16).
  retrieved_at    timestamptz not null,
  created_at      timestamptz not null default now(),
  updated_at      timestamptz not null default now(),
  primary key (home_context_id, local_date, factor),
  -- E23: a home's maxima go with the home. 0016's unique (profile_id, id) is
  -- what this points at, so a row can only name its own household's home.
  constraint daily_maxima_home_context_fkey foreign key (profile_id, home_context_id)
    references public.home_contexts (profile_id, id) on delete cascade
);

create table if not exists public.daily_maxima_recorder (
  -- One row only.
  singleton      boolean primary key default true check (singleton),
  -- Set once by the first run and never moved (E9).
  recording_from date not null,
  last_run_at    timestamptz,
  -- Counts only.
  last_run       jsonb
);

-- Each check is added separately and idempotently, so re-running is safe and a
-- partially applied earlier run is completed rather than erroring.
do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_factor_check') then
    alter table public.daily_maxima add constraint daily_maxima_factor_check
      check (factor in ('air', 'uv'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_unit_check') then
    alter table public.daily_maxima add constraint daily_maxima_unit_check
      check ((factor = 'air' and unit = 'AQI') or (factor = 'uv' and unit = 'UV index'));
  end if;
  -- A value, or a reason it is missing: exactly one of the two.
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_value_missing_check') then
    alter table public.daily_maxima add constraint daily_maxima_value_missing_check
      check ((value is null) = (missing_code is not null));
  end if;
  -- Finite and not negative. NaN sorts above Infinity in Postgres, so the
  -- upper bound refuses it too.
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_value_range_check') then
    alter table public.daily_maxima add constraint daily_maxima_value_range_check
      check (value is null or (value >= 0 and value < 'Infinity'::double precision));
  end if;
  -- An AQI is a whole number (E3).
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_air_integer_check') then
    alter table public.daily_maxima add constraint daily_maxima_air_integer_check
      check (factor <> 'air' or value is null or value = trunc(value));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_missing_code_check') then
    alter table public.daily_maxima add constraint daily_maxima_missing_code_check
      check (missing_code is null or missing_code in ('pending', 'source_gap', 'unavailable'));
  end if;
  -- Each source belongs to one factor (E17).
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_source_check') then
    alter table public.daily_maxima add constraint daily_maxima_source_check
      check (source_code is null
          or (factor = 'air' and source_code in ('airnow_station', 'open_meteo_cams'))
          or (factor = 'uv' and source_code = 'open_meteo_forecast'));
  end if;
  -- A value always says where it came from.
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_value_source_check') then
    alter table public.daily_maxima add constraint daily_maxima_value_source_check
      check (value is null or source_code is not null);
  end if;
  -- A station code exactly for a measured row (E8), and only a short code,
  -- never a site name. Written as a CASE so it is never null, and a CHECK
  -- passes a null: a null source_code takes the ELSE branch, so a row with
  -- no source but a station code is refused (B08 Task 1 fix round 1).
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_station_check') then
    alter table public.daily_maxima add constraint daily_maxima_station_check
      check (case when source_code = 'airnow_station'
                  then station_id is not null and station_id ~ '^[0-9A-Za-z-]{1,32}$'
                  else station_id is null end);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_hours_expected_check') then
    alter table public.daily_maxima add constraint daily_maxima_hours_expected_check
      check (hours_expected between 23 and 25);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_hours_observed_check') then
    alter table public.daily_maxima add constraint daily_maxima_hours_observed_check
      check (hours_observed between 0 and hours_expected);
  end if;
  -- The E3 backstop: no value from less than three quarters of the day.
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_coverage_check') then
    alter table public.daily_maxima add constraint daily_maxima_coverage_check
      check (value is null or hours_observed >= ceil(0.75 * hours_expected));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_method_version_check') then
    alter table public.daily_maxima add constraint daily_maxima_method_version_check
      check (btrim(method_version) <> '' and char_length(method_version) <= 64);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_time_zone_check') then
    alter table public.daily_maxima add constraint daily_maxima_time_zone_check
      check (time_zone = 'America/New_York');
  end if;
  if not exists (select 1 from pg_constraint where conname = 'daily_maxima_recorder_last_run_check') then
    alter table public.daily_maxima_recorder add constraint daily_maxima_recorder_last_run_check
      check (last_run is null or jsonb_typeof(last_run) = 'object');
  end if;
end $$;

-- What GET /api/evidence reads (owner, home, date range), and what the
-- cascade from a home context looks rows up by.
create index if not exists daily_maxima_owner_context_date
  on public.daily_maxima (profile_id, home_context_id, local_date);

alter table public.daily_maxima enable row level security;
alter table public.daily_maxima_recorder enable row level security;

-- No policy, deliberately: every read and write is a route or the recorder
-- using the service role. Supabase's default privileges would otherwise grant
-- anon and authenticated arwdDxtm on these new public tables, so revoking here
-- is what closes that, as 0016 to 0023 do.
revoke all on table public.daily_maxima from anon, authenticated;
revoke all on table public.daily_maxima_recorder from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 3. daily_maxima_schema_version: the probe (E19)
-- ---------------------------------------------------------------------------

create or replace function public.daily_maxima_schema_version()
returns int
language sql
immutable
security invoker
set search_path = public
as $$
  select 1;
$$;

revoke execute on function public.daily_maxima_schema_version() from public, anon, authenticated;
grant execute on function public.daily_maxima_schema_version() to service_role;

-- ---------------------------------------------------------------------------
-- 4. begin_daily_maxima_run: recording_from is set once (E9)
-- ---------------------------------------------------------------------------

create or replace function public.begin_daily_maxima_run(p_first_day date)
returns date
language plpgsql
security invoker
set search_path = public
as $$
declare
  started date;
begin
  if p_first_day is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_first_day is required';
  end if;
  insert into public.daily_maxima_recorder (singleton, recording_from)
    values (true, p_first_day)
    on conflict (singleton) do nothing;
  select r.recording_from into started from public.daily_maxima_recorder r where r.singleton;
  return started;
end;
$$;

revoke execute on function public.begin_daily_maxima_run(date) from public, anon, authenticated;
grant execute on function public.begin_daily_maxima_run(date) to service_role;

-- ---------------------------------------------------------------------------
-- 5. record_daily_maxima: one batch, one transaction (E3, E4, E8, E9)
-- ---------------------------------------------------------------------------
-- Every row is parsed and checked before anything is written, so a malformed
-- row, a duplicate or a date before recording_from refuses the batch whole.
-- A well-formed row that would break a CHECK, or change its home's source,
-- is refused alone and counted; the rest of the batch is written.

create or replace function public.record_daily_maxima(p_rows jsonb)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  allowed  constant text[] := array[
    'profile_id', 'home_context_id', 'local_date', 'factor', 'value', 'unit', 'source_code', 'station_id',
    'method_version', 'time_zone', 'hours_expected', 'hours_observed', 'missing_code', 'retrieved_at'
  ];
  required constant text[] := array[
    'profile_id', 'home_context_id', 'local_date', 'factor', 'unit', 'method_version', 'time_zone',
    'hours_expected', 'hours_observed', 'retrieved_at'
  ];
  strings  constant text[] := array[
    'profile_id', 'home_context_id', 'local_date', 'factor', 'unit', 'source_code', 'station_id',
    'method_version', 'time_zone', 'missing_code', 'retrieved_at'
  ];
  integers constant text[] := array['hours_expected', 'hours_observed'];
  parsed   public.daily_maxima[] := '{}';
  writable public.daily_maxima[] := '{}';
  item     jsonb;
  r        public.daily_maxima;
  rule     text;
  started  date;
  context_owner uuid;
  inserted int := 0;
  updated  int := 0;
  kept     int := 0;
  skipped  int := 0;
  refused  int := 0;
  rules    jsonb := '{}';
begin
  -- Recorder batches run one at a time (800250: see Locks in the header).
  -- First, before anything is read, so a waiting batch sees the rows of the
  -- batch it waited for.
  perform pg_advisory_xact_lock(800250);

  if p_rows is null or jsonb_typeof(p_rows) <> 'array' then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_rows must be a json array';
  end if;
  if jsonb_array_length(p_rows) not between 1 and 1000 then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_rows must hold 1 to 1000 rows';
  end if;

  -- 1. Parse every row.
  for item in select e from jsonb_array_elements(p_rows) e loop
    if jsonb_typeof(item) <> 'object' then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'every row must be a json object';
    end if;
    if exists (select 1 from jsonb_object_keys(item) k where k <> all (allowed)) then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'a row has a key the table does not hold';
    end if;
    if exists (select 1 from unnest(required) k where coalesce(jsonb_typeof(item -> k), 'null') = 'null') then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'a row is missing a required key';
    end if;
    if exists (select 1 from unnest(strings) k
                where coalesce(jsonb_typeof(item -> k), 'null') not in ('null', 'string')) then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'a text field is not a string';
    end if;
    if exists (select 1 from unnest(integers) k where jsonb_typeof(item -> k) <> 'number')
       or coalesce(jsonb_typeof(item -> 'value'), 'null') not in ('null', 'number') then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'a number field is not a number';
    end if;
    if (item ->> 'local_date') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'local_date must be YYYY-MM-DD';
    end if;
    begin
      r := null;
      r.profile_id      := (item ->> 'profile_id')::uuid;
      r.home_context_id := (item ->> 'home_context_id')::uuid;
      r.local_date      := (item ->> 'local_date')::date;
      r.factor          := item ->> 'factor';
      r.value           := (item ->> 'value')::double precision;
      r.unit            := item ->> 'unit';
      r.source_code     := item ->> 'source_code';
      r.station_id      := item ->> 'station_id';
      r.method_version  := item ->> 'method_version';
      r.time_zone       := item ->> 'time_zone';
      r.hours_expected  := (item ->> 'hours_expected')::smallint;
      r.hours_observed  := (item ->> 'hours_observed')::smallint;
      r.missing_code    := item ->> 'missing_code';
      r.retrieved_at    := (item ->> 'retrieved_at')::timestamptz;
    exception
      -- Every data exception (class 22), so no cast error's own message,
      -- which can quote the value, ever leaves the function.
      when data_exception then
        raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001',
          detail = 'a row has a value that is not of its column''s type';
    end;
    parsed := parsed || r;

    -- Each CHECK on the table, tested here with the CHECK's own expression,
    -- in the table's order, so the insert below never meets one. A CHECK
    -- refuses only a false result, never a null one, hence coalesce(.., true).
    rule := case
      when not coalesce(r.factor in ('air', 'uv'), true) then 'factor'
      when not coalesce((r.factor = 'air' and r.unit = 'AQI') or (r.factor = 'uv' and r.unit = 'UV index'), true)
        then 'unit_matches_factor'
      when not coalesce((r.value is null) = (r.missing_code is not null), true) then 'value_or_missing'
      when not coalesce(r.value is null or (r.value >= 0 and r.value < 'Infinity'::double precision), true)
        then 'value_range'
      when not coalesce(r.factor <> 'air' or r.value is null or r.value = trunc(r.value), true) then 'air_integer'
      when not coalesce(r.missing_code is null or r.missing_code in ('pending', 'source_gap', 'unavailable'), true)
        then 'missing_code'
      when not coalesce(r.source_code is null
          or (r.factor = 'air' and r.source_code in ('airnow_station', 'open_meteo_cams'))
          or (r.factor = 'uv' and r.source_code = 'open_meteo_forecast'), true) then 'source_pairs_factor'
      when not coalesce(r.value is null or r.source_code is not null, true) then 'value_needs_source'
      when not coalesce(case when r.source_code = 'airnow_station'
                             then r.station_id is not null and r.station_id ~ '^[0-9A-Za-z-]{1,32}$'
                             else r.station_id is null end, true) then 'station_code'
      when not coalesce(r.hours_expected between 23 and 25, true) then 'hours_expected'
      when not coalesce(r.hours_observed between 0 and r.hours_expected, true) then 'hours_observed'
      when not coalesce(r.value is null or r.hours_observed >= ceil(0.75 * r.hours_expected), true)
        then 'hours_coverage'
      when not coalesce(btrim(r.method_version) <> '' and char_length(r.method_version) <= 64, true)
        then 'method_version'
      when not coalesce(r.time_zone = 'America/New_York', true) then 'time_zone'
    end;
    if rule is null then
      writable := writable || r;
    else
      refused := refused + 1;
      rules := jsonb_set(rules, array[rule], to_jsonb(coalesce((rules ->> rule)::int, 0) + 1));
    end if;
  end loop;

  -- 2. One row per home, date and factor in a batch.
  if exists (select 1 from unnest(parsed) x group by x.home_context_id, x.local_date, x.factor having count(*) > 1) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'a home, date and factor appear twice';
  end if;

  -- 3. Nothing before recording began (E9).
  select d.recording_from into started from public.daily_maxima_recorder d where d.singleton;
  if started is null then
    raise exception 'HALO_BEFORE_RECORDING' using errcode = 'P0001', detail = 'recording has not begun';
  end if;
  if exists (select 1 from unnest(parsed) x where x.local_date < started) then
    raise exception 'HALO_BEFORE_RECORDING' using errcode = 'P0001', detail = 'a row is dated before recording_from';
  end if;

  -- 4. Write, row by row, every row that passed the CHECKs.
  foreach r in array writable loop
    -- The profile first, as every writer of a household takes it, then the
    -- home. A household or home deleted while the run worked is skipped.
    perform 1 from public.profiles p where p.id = r.profile_id for key share;
    if not found then
      skipped := skipped + 1;
      continue;
    end if;
    select h.profile_id into context_owner from public.home_contexts h where h.id = r.home_context_id for key share;
    if not found then
      skipped := skipped + 1;
      continue;
    end if;
    if context_owner <> r.profile_id then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001',
        detail = 'a row names a home context of another household';
    end if;

    -- One source per home, factor and method version (E8): a row naming
    -- another is refused alone, and writes nothing.
    if r.source_code is not null and exists (
      select 1 from public.daily_maxima d
       where d.home_context_id = r.home_context_id and d.factor = r.factor
         and d.method_version = r.method_version
         and d.source_code is not null and d.source_code <> r.source_code
    ) then
      refused := refused + 1;
      rules := jsonb_set(rules, array['source_kind_fixed'], to_jsonb(coalesce((rules ->> 'source_kind_fixed')::int, 0) + 1));
      continue;
    end if;

    insert into public.daily_maxima (
      profile_id, home_context_id, local_date, factor, value, unit, source_code, station_id,
      method_version, time_zone, hours_expected, hours_observed, missing_code, retrieved_at
    ) values (
      r.profile_id, r.home_context_id, r.local_date, r.factor, r.value, r.unit, r.source_code, r.station_id,
      r.method_version, r.time_zone, r.hours_expected, r.hours_observed, r.missing_code, r.retrieved_at
    )
    on conflict (home_context_id, local_date, factor) do nothing;
    if found then
      inserted := inserted + 1;
      continue;
    end if;

    -- Only a pending row is ever rewritten (E4).
    update public.daily_maxima d
       set value = r.value, unit = r.unit, source_code = r.source_code, station_id = r.station_id,
           method_version = r.method_version, time_zone = r.time_zone,
           hours_expected = r.hours_expected, hours_observed = r.hours_observed,
           missing_code = r.missing_code, retrieved_at = r.retrieved_at, updated_at = now()
     where d.home_context_id = r.home_context_id and d.local_date = r.local_date and d.factor = r.factor
       and d.missing_code = 'pending';
    if found then
      updated := updated + 1;
    else
      kept := kept + 1;
    end if;
  end loop;

  return jsonb_build_object('inserted', inserted, 'updated', updated, 'kept', kept, 'skipped', skipped,
                            'refused', refused, 'refusedRules', rules);
end;
$$;

revoke execute on function public.record_daily_maxima(jsonb) from public, anon, authenticated;
grant execute on function public.record_daily_maxima(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 6. finish_daily_maxima_run: the last run's time and counts
-- ---------------------------------------------------------------------------

create or replace function public.finish_daily_maxima_run(p_counts jsonb)
returns timestamptz
language plpgsql
security invoker
set search_path = public
as $$
declare
  finished timestamptz := now();
begin
  if p_counts is null or jsonb_typeof(p_counts) <> 'object' then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_counts must be a json object';
  end if;
  if (select count(*) from jsonb_object_keys(p_counts)) > 32 then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_counts holds at most 32 counts';
  end if;
  -- CASE, so a value is cast to a number only once it is known to be one.
  if exists (select 1 from jsonb_each(p_counts) c
              where case when c.key !~ '^[a-z][a-zA-Z0-9_]{0,63}$' or jsonb_typeof(c.value) <> 'number' then true
                         else (c.value #>> '{}')::numeric < 0
                           or (c.value #>> '{}')::numeric <> trunc((c.value #>> '{}')::numeric) end) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001',
      detail = 'p_counts must map short names to non-negative integers';
  end if;
  -- The rows the run did not write, side by side: skipped (deleted while it
  -- worked) and refused (a broken rule). Counts only, never the rule names.
  if not (p_counts ? 'skipped' and p_counts ? 'refused') then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001',
      detail = 'p_counts must hold skipped and refused';
  end if;
  update public.daily_maxima_recorder d
     set last_run_at = finished, last_run = p_counts
   where d.singleton;
  if not found then
    raise exception 'HALO_RECORDING_NOT_BEGUN' using errcode = 'P0001', detail = 'no run has begun';
  end if;
  return finished;
end;
$$;

revoke execute on function public.finish_daily_maxima_run(jsonb) from public, anon, authenticated;
grant execute on function public.finish_daily_maxima_run(jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 7. A row that is not pending is never rewritten (E4)
-- ---------------------------------------------------------------------------
-- record_daily_maxima already updates only pending rows; this holds the rule
-- for every other writer too, the service role included. A delete is not an
-- update, so the clear and every cascade still remove rows.

create or replace function public.guard_final_daily_maximum()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  raise exception 'HALO_DAILY_MAXIMUM_FINAL' using errcode = 'P0001',
    detail = 'a recorded daily maximum or a final missing day is never rewritten';
end;
$$;

revoke execute on function public.guard_final_daily_maximum() from public, anon, authenticated;

create or replace trigger daily_maxima_final_guard
  before update on public.daily_maxima
  for each row
  when (old.missing_code is distinct from 'pending')
  execute function public.guard_final_daily_maximum();

-- ---------------------------------------------------------------------------
-- Verification (read only). Expect one row, all nine columns true.
-- ---------------------------------------------------------------------------
--   select
--     (select bool_and(relrowsecurity) from pg_class
--       where oid in ('public.daily_maxima'::regclass, 'public.daily_maxima_recorder'::regclass)) as rls_on,
--     (select count(*) from pg_policies
--       where schemaname = 'public' and tablename in ('daily_maxima', 'daily_maxima_recorder')) = 0
--       as no_policies,
--     not exists (
--       select 1 from unnest(array['anon', 'authenticated']) as r
--        cross join unnest(array['public.daily_maxima', 'public.daily_maxima_recorder']) as t
--        where has_any_column_privilege(r, t, 'SELECT')
--           or has_any_column_privilege(r, t, 'INSERT')
--           or has_any_column_privilege(r, t, 'UPDATE')
--           or has_table_privilege(r, t, 'DELETE'))
--       as no_client_access,
--     not exists (
--       select 1 from unnest(array['anon', 'authenticated']) as r
--        cross join unnest(array['public.daily_maxima_schema_version()', 'public.begin_daily_maxima_run(date)',
--                                'public.record_daily_maxima(jsonb)', 'public.finish_daily_maxima_run(jsonb)',
--                                'public.guard_final_daily_maximum()']) as f
--        where has_function_privilege(r, f, 'EXECUTE'))
--       and (select bool_and(has_function_privilege('service_role', f, 'EXECUTE'))
--              from unnest(array['public.daily_maxima_schema_version()', 'public.begin_daily_maxima_run(date)',
--                                'public.record_daily_maxima(jsonb)', 'public.finish_daily_maxima_run(jsonb)']) as f)
--       as functions_service_role_only,
--     (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
--       where n.nspname = 'public' and not p.prosecdef and 'search_path=public' = any (p.proconfig)
--         and p.proname in ('daily_maxima_schema_version', 'begin_daily_maxima_run', 'record_daily_maxima',
--                           'finish_daily_maxima_run', 'guard_final_daily_maximum')) = 5
--       as functions_invoker_pinned,
--     exists (select 1 from pg_trigger
--       where tgrelid = 'public.daily_maxima'::regclass and tgname = 'daily_maxima_final_guard')
--       as final_guard_on,
--     (select count(*) from pg_constraint
--       where conrelid = 'public.daily_maxima'::regclass and contype = 'f' and confdeltype = 'c') = 2
--       as both_links_cascade,
--     (select count(*) from pg_constraint
--       where conrelid = 'public.daily_maxima'::regclass and contype = 'c') = 14
--       as fourteen_checks,
--     exists (select 1 from pg_constraint
--       where conrelid = 'public.daily_maxima'::regclass and conname = 'daily_maxima_station_check'
--         and pg_get_constraintdef(oid) ~ '^CHECK \(\s*CASE')
--       as station_check_closed;
--
-- ---------------------------------------------------------------------------
-- If you need to back out 0025
-- ---------------------------------------------------------------------------
-- The recorder and GET /api/evidence go back to answering a non-retryable 503
-- feature_unavailable from the probe, exactly as before this is applied, so
-- backing out stops recording rather than breaking the existing app. The
-- probe goes first, so they stop at once.
--
-- What is lost: every recorded daily maximum and recording_from, because both
-- tables are dropped. Days already past cannot be recorded again by this
-- method (E9 forbids a backfill), so a back-out leaves a permanent gap from
-- the first recorded day to the reapply. 0024's clear keeps working: it
-- deletes this table only when it exists. daily_scores, home_contexts and
-- everything 0016 to 0024 created are untouched.
--
-- The tested copy of this block is in docs/backend/YOUR_TODO.md, which is what
-- test/migrationBackout.test.mjs runs.
--
-- <!-- backout-0025 -->
-- drop function if exists public.daily_maxima_schema_version();
-- drop function if exists public.begin_daily_maxima_run(date);
-- drop function if exists public.record_daily_maxima(jsonb);
-- drop function if exists public.finish_daily_maxima_run(jsonb);
-- drop table if exists public.daily_maxima;
-- drop table if exists public.daily_maxima_recorder;
-- drop function if exists public.guard_final_daily_maximum();
--
-- Then run: notify pgrst, 'reload schema';

-- ===========================================================================
-- 0026_household_workspace.sql
-- ===========================================================================

-- HALO: the Homeguard workspace, a household's own records in the shared
-- collections (tests and results, home care, kitchen, fish notes, gardens,
-- usage, grower inquiries and the Explore notes, outcomes, projects and
-- engagements), with one read function and one atomic commit function (B11
-- plan, docs/backend/plans/b11-homeguard-workspace.md, Rulings W5 to W12).
--
-- Run once in the Supabase SQL editor, AFTER 0017 (the ledger) and 0016 (home
-- contexts). It does not need 0023, 0024 or 0025 and may go before or after
-- any of them. Safe to re-run.
--
-- Locks: creates one new table and one index, which no other statement can be
-- waiting on. The foreign key to profiles takes a brief SHARE ROW EXCLUSIVE on
-- profiles as it is created, so a new anonymous sign-up could wait a moment.
-- It also adds two triggers to public.operations (sections 4 and 5), each
-- taking a brief SHARE ROW EXCLUSIVE on that table: every ledger claim and
-- settle waits for that moment. Nothing existing is read or rewritten.
--
-- WHAT THIS IS FOR. Homeguard (`/home`) and Explore load each owned
-- collection with `workspace.load` and change it with `workspace.execute`
-- (the frontend's runtime.ts:22-23). Nothing on the server could hold these
-- records. Every record is stored exactly as the client's own row check
-- (lib/frontend/production/home-records.ts, transcribed in
-- lib/workspaceRecords.js) accepted it, as one jsonb value, because the
-- client discards a whole collection for one row it does not recognise and
-- keeps unknown future fields (home-records.ts:20). `id` and `revision` are
-- columns: the server assigns the revision, and the read function writes both
-- over the stored value, so a stored record can never disagree with them.
--
-- ONE COMMIT, ONE TRANSACTION (Ruling W12, the 0023 pattern). The route
-- validates the command and the resulting records in JavaScript and then
-- calls public.commit_household_workspace. A function call is one statement,
-- so every reference check, every delete and upsert at its expected revision,
-- the settle of the caller's own ledger row, and the read of the touched
-- collections commit together or none of them does:
--
--   1. The profile, FOR KEY SHARE, as every writer of a household takes it
--      first (0024's lock order), then the caller's own ledger row, locked,
--      this household's, domain 'workspace', still 'pending'. Otherwise
--      HALO_OPERATION_NOT_PENDING.
--   2. Every reference the command adds names a row this household owns
--      (Ruling W10), held FOR KEY SHARE until the commit. Otherwise
--      HALO_INVALID_REFERENCE.
--   3. Deletes, then upserts, every statement scoped to p_profile_id. A
--      delete or update at a revision that is not the stored one, or a create
--      of an id that exists, is HALO_STALE_REVISION.
--   4. Each touched collection stays within its limits (Ruling W7), or
--      HALO_LIMIT.
--   5. The ledger row is settled 'succeeded' with a receipt of collection
--      names, ids and revisions only, never record content.
--   6. It returns {receipt, changes}: every row of each touched collection.
--
-- So a workspace write exists if and only if its operation is 'succeeded'.
-- The reaper in lib/operations.js settles an abandoned row with a conditional
-- `update ... where status = 'pending'`, and step 1 locks the same row under
-- the same condition, so a reaped row can never become 'succeeded' and a
-- committed write can never be reaped.
--
-- Errors the functions raise, for the routes to map. Each is SQLSTATE P0001
-- with exactly this message; DETAIL says more and never holds record content:
--   HALO_INVALID_INPUT          an argument or p_writes is malformed
--   HALO_OPERATION_NOT_PENDING  the ledger row is missing, settled, another
--                               household's or another domain's
--   HALO_INVALID_REFERENCE      a referenced record or home is not this household's
--   HALO_STALE_REVISION         a record is not there at the revision expected,
--                               or a created id already exists
--   HALO_LIMIT                  a collection would exceed its limits
--   HALO_OPERATION_SETTLED      section 4: a settled 'workspace' row's status may
--                               not change
--
-- Degrades cleanly: until this is applied the B11 routes answer a
-- non-retryable 503 feature_unavailable (a missing function is PGRST202 or
-- 42883, a missing table PGRST205 or 42P01). Nothing else reads this table.
--
-- DELETION. profile_id references profiles ON DELETE CASCADE, so deleting the
-- account deletes every record. A privacy clear all (0024) resets the profile
-- instead of deleting it, so the cascade does not fire there: section 5's
-- trigger deletes the household's rows when that clear settles its own ledger
-- row, inside the clear's transaction (Ruling W8). Clear Journal keeps this
-- table: the week journal is not stored (Ruling W2).
--
-- Retention: rows are kept until the household deletes the record, clears
-- all, or deletes the account. No purge job is defined here on purpose, and no
-- period is invented: the workspace stays behind the `workspace` server flag,
-- off by default, until Vibhav confirms its retention (Ruling W1).
--
-- Privacy: the service role is the only reader. Row level security is on with
-- no policy at all and the default privileges are revoked, so not even the
-- owner can read their own records with their own session.

-- ---------------------------------------------------------------------------
-- 1. The table
-- ---------------------------------------------------------------------------

create table if not exists public.household_workspace_records (
  -- The owner, from the verified session only.
  profile_id  uuid        not null references public.profiles (id) on delete cascade,
  -- One of the fourteen stored collections (home-service.ts; HomeWorkspaceState.tsx:36
  -- less weekJournal and homeTransitions, Rulings W2 and W3).
  collection  text        not null,
  -- HomeServiceRecord.id, app-generated on the device (`test-<uuid>`,
  -- `food-question-...`). Unique per household and collection.
  record_id   text        not null,
  -- A positive integer assigned by the server: 1 on create, + 1 on update.
  revision    integer     not null default 1,
  -- The record as the client's row check accepted it. `id` and `revision` in
  -- it are overwritten by the columns on every read.
  record      jsonb       not null,
  created_at  timestamptz not null default now(),
  updated_at  timestamptz not null default now(),
  primary key (profile_id, collection, record_id)
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'household_workspace_records_collection_check') then
    alter table public.household_workspace_records add constraint household_workspace_records_collection_check
      check (collection in ('tests', 'assets', 'observations', 'gardens', 'usage', 'pantryItems', 'foodQuestions',
                            'fishNotes', 'foodFollows', 'growerInquiries', 'exploreNotes', 'exploreOutcomes',
                            'exploreProjects', 'exploreEngagements'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_workspace_records_id_check') then
    alter table public.household_workspace_records add constraint household_workspace_records_id_check
      check (char_length(record_id) between 1 and 200);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_workspace_records_revision_check') then
    alter table public.household_workspace_records add constraint household_workspace_records_revision_check
      check (revision >= 1);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_workspace_records_record_check') then
    alter table public.household_workspace_records add constraint household_workspace_records_record_check
      check (jsonb_typeof(record) = 'object');
  end if;
  -- A backstop for Ruling W7's 262,144-byte record, which the route checks
  -- first on the JSON it received. jsonb prints a space after every ':' and
  -- ',', so the same record is up to 1.5 times longer as record::text (an
  -- array of one-character numbers goes from 2 bytes an element to 3):
  -- 262,144 * 1.5 = 393,216, so the backstop must sit above that.
  if not exists (select 1 from pg_constraint where conname = 'household_workspace_records_size_check') then
    alter table public.household_workspace_records add constraint household_workspace_records_size_check
      check (octet_length(record::text) <= 400000);
  end if;
end $$;

-- A collection's order: oldest first, the id breaking a tie.
create index if not exists household_workspace_records_owner_created
  on public.household_workspace_records (profile_id, collection, created_at, record_id);

alter table public.household_workspace_records enable row level security;

-- No policy, deliberately: every read and write goes through a route handler
-- using the service role after it has verified the token. Supabase's default
-- privileges would otherwise grant anon and authenticated arwdDxtm on a new
-- public table, so revoking here is what actually closes that.
revoke all on table public.household_workspace_records from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. read_household_workspace: the collections, one consistent read
-- ---------------------------------------------------------------------------
-- p_profile_id is trusted: only the service role may call this, and the routes
-- pass the verified session's user id. Returns {<collection>: [record, ...]}
-- with every requested collection present ([] when it has no rows), oldest
-- first. One statement, so not truncated by PostgREST's max_rows.

create or replace function public.read_household_workspace(p_profile_id uuid, p_collections text[])
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_profile_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id is required';
  end if;
  if p_collections is null or cardinality(p_collections) = 0 or cardinality(p_collections) > 16 then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_collections must name 1 to 16 collections';
  end if;
  return (
    select coalesce(jsonb_object_agg(c.name, coalesce((
             select jsonb_agg(r.record || jsonb_build_object('id', r.record_id, 'revision', r.revision)
                              order by r.created_at, r.record_id)
               from public.household_workspace_records r
              where r.profile_id = p_profile_id and r.collection = c.name), '[]'::jsonb)), '{}'::jsonb)
      from (select distinct unnest(p_collections) as name) c
  );
end;
$$;

revoke execute on function public.read_household_workspace(uuid, text[]) from public, anon, authenticated;
grant execute on function public.read_household_workspace(uuid, text[]) to service_role;

-- ---------------------------------------------------------------------------
-- 3. commit_household_workspace: the atomic write
-- ---------------------------------------------------------------------------
-- p_operation_id is the caller's own ledger row, already claimed by
-- runOperation. p_writes is the route's plan (lib/workspaceStore.js,
-- planWorkspaceCommand), exactly these keys, each optional except collections:
--
--   upserts       [{collection, id, expectedRevision, record}]
--                 expectedRevision null creates (the id must not exist);
--                 a number updates at exactly that stored revision
--   deletes       [{collection, id, expectedRevision}]
--                 a number deletes at exactly that revision; null is a linked
--                 delete (Ruling W11) of a row that may not exist
--   references    [{collection, id}] rows that must be this household's
--   homeContexts  [text] home context ids that must be this household's
--   contexts      [text] ids that must be this household's home context or garden
--   collections   [text] the collections to return, every touched one included
--
-- A record id appears at most once across upserts and deletes per collection.
-- Nothing is written for any refusal.

create or replace function public.commit_household_workspace(
  p_profile_id    uuid,
  p_operation_id  uuid,
  p_writes        jsonb
)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  stored_collections constant text[] := array['tests', 'assets', 'observations', 'gardens', 'usage', 'pantryItems',
    'foodQuestions', 'fishNotes', 'foodFollows', 'growerInquiries', 'exploreNotes', 'exploreOutcomes',
    'exploreProjects', 'exploreEngagements'];
  write_keys   constant text[] := array['collections', 'contexts', 'deletes', 'homeContexts', 'references', 'upserts'];
  w_upserts     jsonb;
  w_deletes     jsonb;
  w_references  jsonb;
  w_homes       jsonb;
  w_contexts    jsonb;
  w_collections text[];
  item          jsonb;
  bad           text;
  touched       int;
  expected_rev  numeric;
  receipt       jsonb;
  stamp         timestamptz := clock_timestamp();
  at            int := 0;
begin
  -- Arguments first: nothing is read or written for a malformed call.
  if p_profile_id is null or p_operation_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id and p_operation_id are required';
  end if;
  if p_writes is null or jsonb_typeof(p_writes) <> 'object' then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_writes must be a JSON object';
  end if;
  select string_agg(k, ', ' order by k) into bad from jsonb_object_keys(p_writes) k where k <> all (write_keys);
  if bad is not null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = format('p_writes has unknown keys: %s', bad);
  end if;
  w_upserts    := coalesce(p_writes -> 'upserts', '[]'::jsonb);
  w_deletes    := coalesce(p_writes -> 'deletes', '[]'::jsonb);
  w_references := coalesce(p_writes -> 'references', '[]'::jsonb);
  w_homes      := coalesce(p_writes -> 'homeContexts', '[]'::jsonb);
  w_contexts   := coalesce(p_writes -> 'contexts', '[]'::jsonb);
  if jsonb_typeof(w_upserts) <> 'array' or jsonb_typeof(w_deletes) <> 'array' or jsonb_typeof(w_references) <> 'array'
     or jsonb_typeof(w_homes) <> 'array' or jsonb_typeof(w_contexts) <> 'array'
     or jsonb_typeof(p_writes -> 'collections') is distinct from 'array' then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'every p_writes value must be an array';
  end if;
  if exists (select 1 from jsonb_array_elements(p_writes -> 'collections') e
              where jsonb_typeof(e) <> 'string' or (e #>> '{}') <> all (stored_collections)) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'collections must name stored collections';
  end if;
  select array_agg(distinct e #>> '{}') into w_collections from jsonb_array_elements(p_writes -> 'collections') e;
  if w_collections is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'collections must not be empty';
  end if;

  for item in select value from jsonb_array_elements(w_upserts) loop
    if jsonb_typeof(item) <> 'object'
       or (select array_agg(k order by k) from jsonb_object_keys(item) k) is distinct from array['collection', 'expectedRevision', 'id', 'record'] then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = format('upserts[%s] must have exactly collection, expectedRevision, id and record', at);
    end if;
    if jsonb_typeof(item -> 'record') <> 'object' or jsonb_typeof(item -> 'id') <> 'string'
       or jsonb_typeof(item -> 'collection') <> 'string' or jsonb_typeof(item -> 'expectedRevision') not in ('number', 'null') then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = format('upserts[%s] has a value of the wrong type', at);
    end if;
    at := at + 1;
  end loop;
  at := 0;
  for item in select value from jsonb_array_elements(w_deletes) loop
    if jsonb_typeof(item) <> 'object'
       or (select array_agg(k order by k) from jsonb_object_keys(item) k) is distinct from array['collection', 'expectedRevision', 'id']
       or jsonb_typeof(item -> 'id') <> 'string' or jsonb_typeof(item -> 'collection') <> 'string'
       or jsonb_typeof(item -> 'expectedRevision') not in ('number', 'null') then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = format('deletes[%s] must have exactly collection, expectedRevision and id', at);
    end if;
    at := at + 1;
  end loop;
  if exists (select 1 from (select value as e from jsonb_array_elements(w_upserts) union all select value from jsonb_array_elements(w_deletes)) w
              where (w.e ->> 'collection') <> all (w_collections)) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'every written collection must be listed in collections';
  end if;
  if exists (select 1 from (select value as e from jsonb_array_elements(w_upserts) union all select value from jsonb_array_elements(w_deletes)) w
              where jsonb_typeof(w.e -> 'expectedRevision') = 'number'
                and ((w.e ->> 'expectedRevision')::numeric < 1 or (w.e ->> 'expectedRevision')::numeric <> trunc((w.e ->> 'expectedRevision')::numeric)
                     or (w.e ->> 'expectedRevision')::numeric >= 2147483647)) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'an expectedRevision must be a whole number from 1';
  end if;
  if exists (select 1 from (select value as e from jsonb_array_elements(w_upserts) union all select value from jsonb_array_elements(w_deletes)) w
              group by w.e ->> 'collection', w.e ->> 'id' having count(*) > 1) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'a record appears more than once';
  end if;
  if exists (select 1 from jsonb_array_elements(w_references) e
              where jsonb_typeof(e) <> 'object' or jsonb_typeof(e -> 'id') <> 'string' or jsonb_typeof(e -> 'collection') <> 'string')
     or exists (select 1 from jsonb_array_elements(w_homes) e where jsonb_typeof(e) <> 'string')
     or exists (select 1 from jsonb_array_elements(w_contexts) e where jsonb_typeof(e) <> 'string') then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'references, homeContexts and contexts are malformed';
  end if;

  -- 1. The profile, then this operation's own ledger row.
  perform 1 from public.profiles p where p.id = p_profile_id for key share;
  perform 1 from public.operations o
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'workspace' and o.status = 'pending'
     for update;
  if not found then
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;

  -- 2. References (Ruling W10). Another household's id is simply not found.
  --    Compared as text, so a value that is not a uuid is not found either.
  --    Locked first, so a concurrent delete waits for this commit.
  perform 1 from public.household_workspace_records r
   where r.profile_id = p_profile_id
     and (r.collection, r.record_id) in (select e ->> 'collection', e ->> 'id' from jsonb_array_elements(w_references) e)
     for key share;
  if exists (
    select 1 from jsonb_array_elements(w_references) e
     where not exists (select 1 from public.household_workspace_records r
                        where r.profile_id = p_profile_id and r.collection = e ->> 'collection' and r.record_id = e ->> 'id')
  ) then
    raise exception 'HALO_INVALID_REFERENCE' using errcode = 'P0001', detail = 'a referenced record is not this household''s';
  end if;
  if exists (
    select 1 from jsonb_array_elements_text(w_homes) h
     where not exists (select 1 from public.home_contexts c where c.profile_id = p_profile_id and c.id::text = h)
  ) then
    raise exception 'HALO_INVALID_REFERENCE' using errcode = 'P0001', detail = 'a home context is not this household''s';
  end if;
  if exists (
    select 1 from jsonb_array_elements_text(w_contexts) x
     where not exists (select 1 from public.home_contexts c where c.profile_id = p_profile_id and c.id::text = x)
       and not exists (select 1 from public.household_workspace_records r
                        where r.profile_id = p_profile_id and r.collection = 'gardens' and r.record_id = x)
  ) then
    raise exception 'HALO_INVALID_REFERENCE' using errcode = 'P0001', detail = 'a sample context is not this household''s';
  end if;

  -- 3. Deletes, then upserts.
  for item in select value from jsonb_array_elements(w_deletes) loop
    if jsonb_typeof(item -> 'expectedRevision') = 'null' then
      delete from public.household_workspace_records r
       where r.profile_id = p_profile_id and r.collection = item ->> 'collection' and r.record_id = item ->> 'id';
    else
      delete from public.household_workspace_records r
       where r.profile_id = p_profile_id and r.collection = item ->> 'collection' and r.record_id = item ->> 'id'
         and r.revision = (item ->> 'expectedRevision')::int;
      get diagnostics touched = row_count;
      if touched <> 1 then
        raise exception 'HALO_STALE_REVISION' using errcode = 'P0001', detail = 'a deleted record is not there at its expected revision';
      end if;
    end if;
  end loop;

  at := 0;
  for item in select value from jsonb_array_elements(w_upserts) loop
    if jsonb_typeof(item -> 'expectedRevision') = 'null' then
      insert into public.household_workspace_records (profile_id, collection, record_id, revision, record, created_at, updated_at)
      values (p_profile_id, item ->> 'collection', item ->> 'id', 1, item -> 'record',
              stamp + at * interval '1 microsecond', stamp)
      on conflict (profile_id, collection, record_id) do nothing;
    else
      expected_rev := (item ->> 'expectedRevision')::numeric;
      update public.household_workspace_records r
         set record = item -> 'record', revision = r.revision + 1, updated_at = now()
       where r.profile_id = p_profile_id and r.collection = item ->> 'collection' and r.record_id = item ->> 'id'
         and r.revision = expected_rev::int;
    end if;
    get diagnostics touched = row_count;
    if touched <> 1 then
      raise exception 'HALO_STALE_REVISION' using errcode = 'P0001', detail = 'a record is not there at its expected revision, or a created id exists';
    end if;
    at := at + 1;
  end loop;

  -- 4. Limits (Ruling W7), for every touched collection.
  if exists (
    select 1 from public.household_workspace_records r
     where r.profile_id = p_profile_id and r.collection = any (w_collections)
     group by r.collection
    having count(*) > 1000 or sum(octet_length(r.record::text)) > 1500000
  ) then
    raise exception 'HALO_LIMIT' using errcode = 'P0001', detail = 'a collection would exceed its record or size limit';
  end if;

  -- 5. Settle this operation's own row: names, ids and revisions only.
  receipt := jsonb_build_object(
    'status', 'succeeded',
    'collections', to_jsonb(w_collections),
    'affected', coalesce((
      select jsonb_agg(jsonb_build_object('collection', r.collection, 'id', r.record_id, 'revision', r.revision)
                       order by r.collection, r.record_id)
        from public.household_workspace_records r
       where r.profile_id = p_profile_id
         and (r.collection, r.record_id) in (select e ->> 'collection', e ->> 'id' from jsonb_array_elements(w_upserts) e)), '[]'::jsonb),
    'removed', coalesce((
      select jsonb_agg(jsonb_build_object('collection', e ->> 'collection', 'id', e ->> 'id'))
        from jsonb_array_elements(w_deletes) e), '[]'::jsonb),
    'unresolvedOperations', '[]'::jsonb
  );
  update public.operations o
     set status = 'succeeded', result = receipt, updated_at = now()
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'workspace' and o.status = 'pending';
  get diagnostics touched = row_count;
  if touched <> 1 then
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;

  -- 6. The touched collections as they now stand, read in this transaction.
  return jsonb_build_object('receipt', receipt, 'changes', public.read_household_workspace(p_profile_id, w_collections));
end;
$$;

revoke execute on function public.commit_household_workspace(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.commit_household_workspace(uuid, uuid, jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 4. A settled 'workspace' operation keeps its status (the 0023 guard)
-- ---------------------------------------------------------------------------
-- runOperation settles by operation id alone and settles 'failed' whenever
-- its execute throws. If the commit function committed and its response was
-- lost, that settle would turn a 'succeeded' row whose records were written
-- into 'failed'. In the 'workspace' domain only, a row that has left
-- 'pending' may not change its status: the settle fails, lib/operations.js
-- logs it rather than throwing, and the row keeps telling the truth.

create or replace function public.guard_settled_workspace_operation()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  raise exception 'HALO_OPERATION_SETTLED' using errcode = 'P0001',
    detail = format('operation %s is already %s', old.operation_id, old.status);
end;
$$;

revoke execute on function public.guard_settled_workspace_operation() from public, anon, authenticated;

create or replace trigger operations_workspace_settled_guard
  before update on public.operations
  for each row
  when (old.domain = 'workspace' and old.status <> 'pending' and new.status is distinct from old.status)
  execute function public.guard_settled_workspace_operation();

-- ---------------------------------------------------------------------------
-- 5. Clear all removes the workspace too (Ruling W8)
-- ---------------------------------------------------------------------------
-- 0024's clear_household_records settles its own 'privacy.clear.all' row
-- from 'pending' to 'succeeded' as its last write, in its own transaction.
-- This trigger deletes the same household's workspace rows at that moment,
-- so they go with the clear or not at all, without changing 0024. A clear
-- that refuses raises before it settles, so it deletes nothing here. Clear
-- Journal ('privacy.clear.journal') does not touch the workspace.

create or replace function public.clear_workspace_with_privacy_clear()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  delete from public.household_workspace_records r where r.profile_id = new.profile_id;
  return null;
end;
$$;

revoke execute on function public.clear_workspace_with_privacy_clear() from public, anon, authenticated;

create or replace trigger operations_privacy_clear_workspace
  after update on public.operations
  for each row
  when (new.domain = 'privacy' and new.kind = 'privacy.clear.all' and old.status = 'pending'
        and new.status = 'succeeded' and new.profile_id is not null)
  execute function public.clear_workspace_with_privacy_clear();

-- What a clear all would remove from the workspace, for the privacy review's
-- counts (lib/privacyStore.js merges it into privacy_counts' answer).
create or replace function public.workspace_privacy_counts(p_profile_id uuid)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_profile_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id is required';
  end if;
  return jsonb_build_object('household_workspace_records',
    (select count(*) from public.household_workspace_records r where r.profile_id = p_profile_id));
end;
$$;

revoke execute on function public.workspace_privacy_counts(uuid) from public, anon, authenticated;
grant execute on function public.workspace_privacy_counts(uuid) to service_role;

