-- ===========================================================================
-- 0028_household_attachments.sql
-- ===========================================================================

-- HALO: private photo attachments for the Homeguard workspace (test reports,
-- moisture observation photos and Explore note photos): one row per
-- processed file, a queue of storage objects to delete, the functions the
-- attachment routes call, the triggers that keep workspace references honest,
-- and the private storage bucket (B14 plan,
-- docs/backend/plans/b14-private-attachments.md, Rulings A1 to A12).
--
-- Run once in the Supabase SQL editor, AFTER 0017 (the ledger) and 0026 (the
-- workspace). It does not need 0024, 0025 or 0027 and may go before or after
-- any of them. Safe to re-run.
--
-- Locks: creates two new tables. The foreign key to profiles takes a brief
-- SHARE ROW EXCLUSIVE on profiles as it is created. It adds two triggers to
-- public.operations and two to public.household_workspace_records, each
-- taking a brief SHARE ROW EXCLUSIVE on that table as it is created: a ledger
-- claim or a workspace save at that moment waits for it. Nothing existing is
-- read or rewritten. Section 9 inserts one row into storage.buckets when the
-- storage schema exists.
--
-- WHAT THIS IS FOR. The app uploads a reviewed photo with POST
-- /api/attachments (the frontend's runtime.ts:24). The route decodes and
-- re-encodes it with sharp, so no EXIF, GPS or other metadata survives, writes
-- the bytes to the private bucket with the service role, and records it here.
-- A test report is linked to its test at once (the test record gains the
-- file's descriptor); an observation or note photo is staged under the
-- client's record id and linked by the workspace write that references it.
--
-- ONE UPLOAD, TWO STEPS (Ruling A9). reserve_attachment_object queues the
-- object's path for deletion an hour from now BEFORE the bytes are written;
-- commit_household_attachment then records the row, clears that entry and
-- settles the caller's own ledger row in one transaction. A process that dies
-- between the two leaves only a queued object, which the sweep deletes.
--
-- DELETION. Storage objects cannot be deleted from SQL. Every deleted
-- household_attachments row (a removal, a record's deletion, a dropped
-- reference, a privacy clear all, the account's deletion cascade, a staged
-- upload's expiry) queues its object in attachment_object_sweep through a
-- trigger, and the routes delete queued objects through the Storage API: the
-- remove route at once, the privacy clear route after a clear all, and
-- /api/cron/daily for everything due. due_attachment_objects never lists an
-- object whose row still exists.
--
-- Errors the functions raise, for the routes to map. Each is SQLSTATE P0001
-- with exactly this message; DETAIL never holds a file name:
--   HALO_INVALID_INPUT          an argument is malformed, or the object was not reserved
--   HALO_OPERATION_NOT_PENDING  the ledger row is missing, settled, another
--                               household's or another domain's
--   HALO_INVALID_REFERENCE      the test is not this household's, or a workspace
--                               record names a file that is not ready, not this
--                               household's, or not staged for that record
--   HALO_NOT_FOUND              the file is not this household's
--   HALO_STALE_REVISION         the file is not at the revision expected
--   HALO_LIMIT                  a record or household file limit (Ruling A3)
--   HALO_OPERATION_SETTLED      a settled 'attachments' row's status may not change
--
-- Degrades cleanly: until this is applied the attachment routes answer
-- "unavailable" (Ruling A6) and a workspace write naming a file is refused, as
-- before (B11 Ruling W4).
--
-- Retention (Ruling A1, proposed): a file is kept until the person removes it,
-- drops it from its record, removes the record, clears all, or deletes the
-- account; a staged upload never linked expires after 24 hours. The routes
-- stay behind the `attachments` server flag, off by default.
--
-- Privacy: the service role is the only reader or writer, of the rows and of
-- the bucket. Row level security is on with no policy, the default privileges
-- are revoked, and no storage policy names the bucket.

-- ---------------------------------------------------------------------------
-- 1. The tables
-- ---------------------------------------------------------------------------

create table if not exists public.household_attachments (
  -- Server generated; the client never names a new one.
  attachment_id    uuid        primary key,
  -- The owner, from the verified session only.
  profile_id       uuid        not null references public.profiles (id) on delete cascade,
  -- The upload's own ledger operation.
  operation_id     uuid        not null unique,
  -- The workspace collection and the client's stable record id it belongs to.
  collection       text        not null,
  record_id        text        not null,
  -- Always 1 today; removal checks it exactly.
  revision         integer     not null default 1,
  -- The reviewed name the person chose. Private text.
  name             text        not null,
  -- The processed file, never the original.
  mime             text        not null,
  bytes            integer     not null,
  width            integer     not null,
  height           integer     not null,
  status           text        not null default 'ready',
  metadata_removed boolean     not null default true,
  -- <profile id>/<attachment id>, built here, never from client input.
  object_path      text        not null unique,
  -- True once a saved record references it (a report is linked at upload).
  linked           boolean     not null default false,
  created_at       timestamptz not null default now(),
  linked_at        timestamptz
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'household_attachments_collection_check') then
    alter table public.household_attachments add constraint household_attachments_collection_check
      check (collection in ('tests', 'observations', 'exploreNotes'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_attachments_record_check') then
    alter table public.household_attachments add constraint household_attachments_record_check
      check (char_length(record_id) between 1 and 200);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_attachments_revision_check') then
    alter table public.household_attachments add constraint household_attachments_revision_check
      check (revision >= 1);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_attachments_name_check') then
    alter table public.household_attachments add constraint household_attachments_name_check
      check (char_length(name) between 1 and 200);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_attachments_file_check') then
    alter table public.household_attachments add constraint household_attachments_file_check
      check (mime in ('image/jpeg', 'image/png', 'image/webp') and bytes between 1 and 15728640
             and width between 1 and 100000 and height between 1 and 100000);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_attachments_status_check') then
    alter table public.household_attachments add constraint household_attachments_status_check
      check (status in ('quarantined', 'ready', 'rejected') and metadata_removed);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_attachments_path_check') then
    alter table public.household_attachments add constraint household_attachments_path_check
      check (object_path = profile_id::text || '/' || attachment_id::text);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'household_attachments_linked_check') then
    alter table public.household_attachments add constraint household_attachments_linked_check
      check (linked = (linked_at is not null));
  end if;
end $$;

create index if not exists household_attachments_owner_record
  on public.household_attachments (profile_id, collection, record_id);
create index if not exists household_attachments_staged
  on public.household_attachments (created_at) where not linked;

alter table public.household_attachments enable row level security;
revoke all on table public.household_attachments from anon, authenticated;

-- Storage objects to delete: a path and when it is due. No owner column and no
-- foreign key, so an account's deletion cascade cannot take its queue with it.
create table if not exists public.attachment_object_sweep (
  object_path text        primary key,
  due_at      timestamptz not null default now(),
  created_at  timestamptz not null default now()
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'attachment_object_sweep_path_check') then
    alter table public.attachment_object_sweep add constraint attachment_object_sweep_path_check
      check (object_path ~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}/[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$');
  end if;
end $$;

create index if not exists attachment_object_sweep_due on public.attachment_object_sweep (due_at);

alter table public.attachment_object_sweep enable row level security;
revoke all on table public.attachment_object_sweep from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 2. The descriptor and the reads
-- ---------------------------------------------------------------------------
-- The frontend's HomeAttachment (home-service.ts:31-35), exactly.

create or replace function public.household_attachment_json(a public.household_attachments)
returns jsonb
language sql
immutable
security invoker
set search_path = public
as $$
  select jsonb_build_object('id', a.attachment_id::text, 'revision', a.revision, 'name', a.name, 'mime', a.mime,
                            'bytes', a.bytes, 'status', a.status, 'metadataRemoved', a.metadata_removed);
$$;

revoke execute on function public.household_attachment_json(public.household_attachments) from public, anon, authenticated;
grant execute on function public.household_attachment_json(public.household_attachments) to service_role;

-- One file of this household, with where it belongs, or null. Another
-- household's id is simply not found.
create or replace function public.read_household_attachment(p_profile_id uuid, p_attachment_id uuid)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_profile_id is null or p_attachment_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id and p_attachment_id are required';
  end if;
  return (
    select public.household_attachment_json(a)
           || jsonb_build_object('collection', a.collection, 'recordId', a.record_id, 'objectPath', a.object_path,
                                 'linked', a.linked, 'width', a.width, 'height', a.height)
      from public.household_attachments a
     where a.profile_id = p_profile_id and a.attachment_id = p_attachment_id
  );
end;
$$;

revoke execute on function public.read_household_attachment(uuid, uuid) from public, anon, authenticated;
grant execute on function public.read_household_attachment(uuid, uuid) to service_role;

-- The household's usage, for the routes' early limit answer before any claim
-- (the commit checks again under its locks): {files, bytes, recordFiles}.
create or replace function public.household_attachment_usage(p_profile_id uuid, p_collection text, p_record_id text)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_profile_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id is required';
  end if;
  return jsonb_build_object(
    'files', (select count(*) from public.household_attachments a where a.profile_id = p_profile_id),
    'bytes', (select coalesce(sum(a.bytes), 0) from public.household_attachments a where a.profile_id = p_profile_id),
    'recordFiles', (select count(*) from public.household_attachments a
                     where a.profile_id = p_profile_id and a.collection = p_collection and a.record_id = p_record_id));
end;
$$;

revoke execute on function public.household_attachment_usage(uuid, text, text) from public, anon, authenticated;
grant execute on function public.household_attachment_usage(uuid, text, text) to service_role;

-- The files a workspace write names, for the route's early answer (Ruling A7):
-- the descriptor of each id that is this household's, ready and staged or
-- linked for exactly this collection and record. The trigger in section 6 is
-- the authority under its locks.
create or replace function public.check_attachment_references(p_profile_id uuid, p_collection text, p_record_id text, p_ids text[])
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_profile_id is null or p_ids is null or cardinality(p_ids) > 100 then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id and at most 100 ids are required';
  end if;
  return coalesce((
    select jsonb_agg(public.household_attachment_json(a) order by a.attachment_id)
      from public.household_attachments a
     where a.profile_id = p_profile_id and a.collection = p_collection and a.record_id = p_record_id
       and a.status = 'ready' and a.attachment_id::text = any (p_ids)), '[]'::jsonb);
end;
$$;

revoke execute on function public.check_attachment_references(uuid, text, text, text[]) from public, anon, authenticated;
grant execute on function public.check_attachment_references(uuid, text, text, text[]) to service_role;

-- ---------------------------------------------------------------------------
-- 3. The upload: reserve, then commit
-- ---------------------------------------------------------------------------

create or replace function public.reserve_attachment_object(p_profile_id uuid, p_operation_id uuid, p_attachment_id uuid)
returns text
language plpgsql
security invoker
set search_path = public
as $$
declare
  path text;
begin
  if p_profile_id is null or p_operation_id is null or p_attachment_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'every argument is required';
  end if;
  perform 1 from public.operations o
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'attachments' and o.status = 'pending';
  if not found then
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;
  path := p_profile_id::text || '/' || p_attachment_id::text;
  if exists (select 1 from public.household_attachments a where a.attachment_id = p_attachment_id) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'the attachment id exists';
  end if;
  insert into public.attachment_object_sweep (object_path, due_at) values (path, now() + interval '1 hour')
  on conflict (object_path) do nothing;
  return path;
end;
$$;

revoke execute on function public.reserve_attachment_object(uuid, uuid, uuid) from public, anon, authenticated;
grant execute on function public.reserve_attachment_object(uuid, uuid, uuid) to service_role;

-- p_file: exactly {attachmentId, collection, recordId, name, mime, bytes, width, height},
-- the processed file the route already wrote to the reserved path.
-- Returns {receipt, attachment, changes}.
create or replace function public.commit_household_attachment(p_profile_id uuid, p_operation_id uuid, p_file jsonb)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  f_id         uuid;
  f_collection text;
  f_record     text;
  path         text;
  stored       public.household_attachments;
  descriptor   jsonb;
  receipt      jsonb;
  touched      int;
  names        text[] := '{}';
begin
  if p_profile_id is null or p_operation_id is null or p_file is null or jsonb_typeof(p_file) <> 'object'
     or (select array_agg(k order by k) from jsonb_object_keys(p_file) k)
        is distinct from array['attachmentId', 'bytes', 'collection', 'height', 'mime', 'name', 'recordId', 'width'] then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_file must have exactly the eight file keys';
  end if;
  if jsonb_typeof(p_file -> 'attachmentId') <> 'string' or jsonb_typeof(p_file -> 'collection') <> 'string'
     or jsonb_typeof(p_file -> 'recordId') <> 'string' or jsonb_typeof(p_file -> 'name') <> 'string'
     or jsonb_typeof(p_file -> 'mime') <> 'string' or jsonb_typeof(p_file -> 'bytes') <> 'number'
     or jsonb_typeof(p_file -> 'width') <> 'number' or jsonb_typeof(p_file -> 'height') <> 'number'
     or (p_file ->> 'attachmentId') !~ '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'a p_file value has the wrong type';
  end if;
  f_id := (p_file ->> 'attachmentId')::uuid;
  f_collection := p_file ->> 'collection';
  f_record := p_file ->> 'recordId';
  path := p_profile_id::text || '/' || f_id::text;

  -- The profile, then this operation's own ledger row (0024's lock order).
  perform 1 from public.profiles p where p.id = p_profile_id for key share;
  perform 1 from public.operations o
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'attachments' and o.status = 'pending'
     for update;
  if not found then
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;
  perform 1 from public.attachment_object_sweep s where s.object_path = path for update;
  if not found then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'the object was not reserved';
  end if;

  -- Limits (Ruling A3): 20 files a record, 200 files and 500 MiB a household.
  if (select count(*) from public.household_attachments a
       where a.profile_id = p_profile_id and a.collection = f_collection and a.record_id = f_record) >= 20
     or (select count(*) from public.household_attachments a where a.profile_id = p_profile_id) >= 200
     or (select coalesce(sum(a.bytes), 0) from public.household_attachments a where a.profile_id = p_profile_id)
        + (p_file ->> 'bytes')::numeric > 524288000 then
    raise exception 'HALO_LIMIT' using errcode = 'P0001', detail = 'a record or household file limit';
  end if;

  -- A report belongs to a saved test of this household (Ruling A7).
  if f_collection = 'tests' then
    perform 1 from public.household_workspace_records r
     where r.profile_id = p_profile_id and r.collection = 'tests' and r.record_id = f_record
       for update;
    if not found then
      raise exception 'HALO_INVALID_REFERENCE' using errcode = 'P0001', detail = 'the test is not this household''s';
    end if;
  end if;

  insert into public.household_attachments
    (attachment_id, profile_id, operation_id, collection, record_id, name, mime, bytes, width, height,
     object_path, linked, linked_at)
  values
    (f_id, p_profile_id, p_operation_id, f_collection, f_record, p_file ->> 'name', p_file ->> 'mime',
     (p_file ->> 'bytes')::int, (p_file ->> 'width')::int, (p_file ->> 'height')::int,
     path, f_collection = 'tests', case when f_collection = 'tests' then now() end)
  returning * into stored;
  delete from public.attachment_object_sweep s where s.object_path = path;
  descriptor := public.household_attachment_json(stored);

  if f_collection = 'tests' then
    update public.household_workspace_records r
       set record = jsonb_set(r.record, '{attachments}',
                              coalesce(case when jsonb_typeof(r.record -> 'attachments') = 'array' then r.record -> 'attachments' end, '[]'::jsonb)
                              || jsonb_build_array(descriptor)),
           revision = r.revision + 1, updated_at = now()
     where r.profile_id = p_profile_id and r.collection = 'tests' and r.record_id = f_record;
    names := array['tests'];
  end if;

  -- Settle this operation's own row: the id and collection names only, never the name.
  receipt := jsonb_build_object('status', 'succeeded', 'attachmentId', f_id::text, 'collections', to_jsonb(names),
                                'unresolvedOperations', '[]'::jsonb);
  update public.operations o
     set status = 'succeeded', result = receipt, updated_at = now()
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'attachments' and o.status = 'pending';
  get diagnostics touched = row_count;
  if touched <> 1 then
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;

  return jsonb_build_object('receipt', receipt, 'attachment', descriptor,
    'changes', case when cardinality(names) > 0 then public.read_household_workspace(p_profile_id, names) else '{}'::jsonb end);
end;
$$;

revoke execute on function public.commit_household_attachment(uuid, uuid, jsonb) from public, anon, authenticated;
grant execute on function public.commit_household_attachment(uuid, uuid, jsonb) to service_role;

-- ---------------------------------------------------------------------------
-- 4. Removal at an exact revision (Ruling A8)
-- ---------------------------------------------------------------------------
-- Deletes the row (section 7 queues its object), removes the reference from
-- the record that holds it (revision + 1; entered results stay), settles the
-- ledger row and returns {receipt, objectPath, changes}: the canonical rows of
-- the file's collection, never empty.

create or replace function public.remove_household_attachment(p_profile_id uuid, p_operation_id uuid, p_attachment_id uuid, p_expected_revision integer)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  stored  public.household_attachments;
  id_text text;
  receipt jsonb;
  touched int;
begin
  if p_profile_id is null or p_operation_id is null or p_attachment_id is null or p_expected_revision is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'every argument is required';
  end if;
  perform 1 from public.profiles p where p.id = p_profile_id for key share;
  perform 1 from public.operations o
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'attachments' and o.status = 'pending'
     for update;
  if not found then
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;
  -- Lock order: the record that holds the file, then the file. A workspace
  -- write locks its record first and its link trigger then locks the files it
  -- names, so taking the file first here could deadlock with that write. The
  -- record lock is the one a plain UPDATE takes (it does not block another
  -- commit's key share on the same record). A staged file may have no record.
  select * into stored from public.household_attachments a
   where a.attachment_id = p_attachment_id and a.profile_id = p_profile_id;
  if found then
    perform 1 from public.household_workspace_records r
     where r.profile_id = p_profile_id and r.collection = stored.collection and r.record_id = stored.record_id
       for no key update;
  end if;
  select * into stored from public.household_attachments a
   where a.attachment_id = p_attachment_id and a.profile_id = p_profile_id
     for update;
  if not found then
    raise exception 'HALO_NOT_FOUND' using errcode = 'P0001';
  end if;
  if stored.revision <> p_expected_revision then
    raise exception 'HALO_STALE_REVISION' using errcode = 'P0001';
  end if;
  id_text := stored.attachment_id::text;

  delete from public.household_attachments a where a.attachment_id = stored.attachment_id;

  update public.household_workspace_records r
     set record = case r.collection
           when 'tests' then jsonb_set(r.record, '{attachments}', coalesce((
             select jsonb_agg(e order by n) from jsonb_array_elements(r.record -> 'attachments') with ordinality t(e, n)
              where e ->> 'id' is distinct from id_text), '[]'::jsonb))
           when 'observations' then (r.record - 'photoAttachmentId' - 'photoAttachmentRevision') || jsonb_build_object('photoName', '')
           else r.record - 'photoAttachment'
         end,
         revision = r.revision + 1, updated_at = now()
   where r.profile_id = p_profile_id and r.collection = stored.collection and r.record_id = stored.record_id
     and case r.collection
           when 'tests' then jsonb_typeof(r.record -> 'attachments') = 'array'
                             and exists (select 1 from jsonb_array_elements(r.record -> 'attachments') e where e ->> 'id' = id_text)
           when 'observations' then r.record ->> 'photoAttachmentId' = id_text
           else r.record -> 'photoAttachment' ->> 'id' = id_text
         end;

  receipt := jsonb_build_object('status', 'succeeded', 'attachmentId', id_text,
                                'collections', jsonb_build_array(stored.collection), 'unresolvedOperations', '[]'::jsonb);
  update public.operations o
     set status = 'succeeded', result = receipt, updated_at = now()
   where o.operation_id = p_operation_id and o.profile_id = p_profile_id
     and o.domain = 'attachments' and o.status = 'pending';
  get diagnostics touched = row_count;
  if touched <> 1 then
    raise exception 'HALO_OPERATION_NOT_PENDING' using errcode = 'P0001';
  end if;

  return jsonb_build_object('receipt', receipt, 'objectPath', stored.object_path,
    'changes', public.read_household_workspace(p_profile_id, array[stored.collection]));
end;
$$;

revoke execute on function public.remove_household_attachment(uuid, uuid, uuid, integer) from public, anon, authenticated;
grant execute on function public.remove_household_attachment(uuid, uuid, uuid, integer) to service_role;

-- ---------------------------------------------------------------------------
-- 5. A settled 'attachments' operation keeps its status (the 0026 guard)
-- ---------------------------------------------------------------------------
-- The commit and remove functions settle their own row 'succeeded'. If the
-- response is lost, runOperation would settle it 'failed' over a file that
-- exists or is gone. A row that has left 'pending' may not change status.

create or replace function public.guard_settled_attachments_operation()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  raise exception 'HALO_OPERATION_SETTLED' using errcode = 'P0001',
    detail = format('operation %s is already %s', old.operation_id, old.status);
end;
$$;

revoke execute on function public.guard_settled_attachments_operation() from public, anon, authenticated;

create or replace trigger operations_attachments_settled_guard
  before update on public.operations
  for each row
  when (old.domain = 'attachments' and old.status <> 'pending' and new.status is distinct from old.status)
  execute function public.guard_settled_attachments_operation();

-- ---------------------------------------------------------------------------
-- 6. Workspace references (Ruling A7)
-- ---------------------------------------------------------------------------
-- Before a tests, observations or exploreNotes record is stored: every file
-- it references must be this household's, ready, staged or linked for this
-- collection and record id, at the referenced revision, and named once; the
-- stored reference becomes the file's canonical descriptor and the file is
-- marked linked. A file linked to this record that the record no longer
-- references is deleted (section 7 queues its object). After a record is
-- deleted, its files go with it.

create or replace function public.link_workspace_attachments()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
declare
  refs  jsonb := '[]'::jsonb;
  ref   jsonb;
  canon jsonb := '[]'::jsonb;
  ids   text[] := '{}';
  found_file public.household_attachments;
begin
  if new.collection = 'tests' then
    if jsonb_typeof(new.record -> 'attachments') = 'array' then
      refs := new.record -> 'attachments';
    elsif new.record ? 'attachments' then
      raise exception 'HALO_INVALID_REFERENCE' using errcode = 'P0001', detail = 'attachments must be a list';
    end if;
  elsif new.collection = 'observations' then
    if jsonb_typeof(new.record -> 'photoAttachmentId') = 'string' and new.record ->> 'photoAttachmentId' <> '' then
      refs := jsonb_build_array(jsonb_build_object('id', new.record -> 'photoAttachmentId', 'revision', new.record -> 'photoAttachmentRevision'));
    end if;
  elsif new.collection = 'exploreNotes' then
    if new.record ? 'photoAttachment' and jsonb_typeof(new.record -> 'photoAttachment') <> 'null' then
      refs := jsonb_build_array(new.record -> 'photoAttachment');
    end if;
  end if;

  for ref in select value from jsonb_array_elements(refs) loop
    if jsonb_typeof(ref) <> 'object' or jsonb_typeof(ref -> 'id') <> 'string' or jsonb_typeof(ref -> 'revision') <> 'number'
       or (ref ->> 'id') = any (ids) then
      raise exception 'HALO_INVALID_REFERENCE' using errcode = 'P0001', detail = 'a file reference is malformed or repeated';
    end if;
    select * into found_file from public.household_attachments a
     where a.profile_id = new.profile_id and a.attachment_id::text = ref ->> 'id'
       and a.collection = new.collection and a.record_id = new.record_id and a.status = 'ready'
       for update;
    if not found or (ref ->> 'revision')::numeric <> found_file.revision then
      raise exception 'HALO_INVALID_REFERENCE' using errcode = 'P0001', detail = 'a referenced file is not this record''s';
    end if;
    ids := ids || (ref ->> 'id');
    canon := canon || jsonb_build_array(public.household_attachment_json(found_file));
    if not found_file.linked then
      update public.household_attachments a set linked = true, linked_at = now() where a.attachment_id = found_file.attachment_id;
    end if;
  end loop;

  -- References this write dropped.
  delete from public.household_attachments a
   where a.profile_id = new.profile_id and a.collection = new.collection and a.record_id = new.record_id
     and a.linked and not (a.attachment_id::text = any (ids));

  if new.collection = 'tests' and jsonb_typeof(new.record -> 'attachments') = 'array' then
    new.record := jsonb_set(new.record, '{attachments}', canon);
  elsif new.collection = 'observations' and jsonb_array_length(canon) = 1 then
    new.record := new.record || jsonb_build_object('photoAttachmentRevision', canon -> 0 -> 'revision', 'photoMetadataRemoved', true);
  elsif new.collection = 'exploreNotes' and jsonb_array_length(canon) = 1 then
    new.record := jsonb_set(new.record, '{photoAttachment}', jsonb_build_object(
      'id', canon -> 0 -> 'id', 'revision', canon -> 0 -> 'revision', 'name', canon -> 0 -> 'name', 'metadataRemoved', true));
  end if;
  return new;
end;
$$;

revoke execute on function public.link_workspace_attachments() from public, anon, authenticated;

create or replace trigger household_workspace_records_link_attachments
  before insert or update of record on public.household_workspace_records
  for each row
  when (new.collection in ('tests', 'observations', 'exploreNotes'))
  execute function public.link_workspace_attachments();

create or replace function public.delete_record_attachments()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  delete from public.household_attachments a
   where a.profile_id = old.profile_id and a.collection = old.collection and a.record_id = old.record_id;
  return null;
end;
$$;

revoke execute on function public.delete_record_attachments() from public, anon, authenticated;

create or replace trigger household_workspace_records_delete_attachments
  after delete on public.household_workspace_records
  for each row
  when (old.collection in ('tests', 'observations', 'exploreNotes'))
  execute function public.delete_record_attachments();

-- ---------------------------------------------------------------------------
-- 7. Every deleted file queues its object
-- ---------------------------------------------------------------------------

create or replace function public.queue_attachment_object()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  insert into public.attachment_object_sweep (object_path, due_at) values (old.object_path, now())
  on conflict (object_path) do update set due_at = least(public.attachment_object_sweep.due_at, excluded.due_at);
  return null;
end;
$$;

revoke execute on function public.queue_attachment_object() from public, anon, authenticated;

create or replace trigger household_attachments_queue_object
  after delete on public.household_attachments
  for each row
  execute function public.queue_attachment_object();

-- Clear all removes every file (0024 resets the profile rather than deleting
-- it, so the cascade does not fire there; the 0026 pattern, B11 Ruling W8).
-- Clear Journal keeps them.
create or replace function public.clear_attachments_with_privacy_clear()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  delete from public.household_attachments a where a.profile_id = new.profile_id;
  return null;
end;
$$;

revoke execute on function public.clear_attachments_with_privacy_clear() from public, anon, authenticated;

create or replace trigger operations_privacy_clear_attachments
  after update on public.operations
  for each row
  when (new.domain = 'privacy' and new.kind = 'privacy.clear.all' and old.status = 'pending'
        and new.status = 'succeeded' and new.profile_id is not null)
  execute function public.clear_attachments_with_privacy_clear();

-- ---------------------------------------------------------------------------
-- 8. Counts, expiry and the sweep's queue
-- ---------------------------------------------------------------------------

create or replace function public.attachment_privacy_counts(p_profile_id uuid)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_profile_id is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_profile_id is required';
  end if;
  return jsonb_build_object('household_attachments',
    (select count(*) from public.household_attachments a where a.profile_id = p_profile_id));
end;
$$;

revoke execute on function public.attachment_privacy_counts(uuid) from public, anon, authenticated;
grant execute on function public.attachment_privacy_counts(uuid) to service_role;

-- Staged uploads never linked within 24 hours are deleted (Ruling A1).
create or replace function public.expire_staged_attachments(p_limit integer)
returns integer
language plpgsql
security invoker
set search_path = public
as $$
declare
  removed int;
begin
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_limit must be 1 to 1000';
  end if;
  delete from public.household_attachments a
   where a.attachment_id in (
     select s.attachment_id from public.household_attachments s
      where not s.linked and s.created_at < now() - interval '24 hours'
      order by s.created_at limit p_limit
      for update skip locked)
     and not a.linked;
  get diagnostics removed = row_count;
  return removed;
end;
$$;

revoke execute on function public.expire_staged_attachments(integer) from public, anon, authenticated;
grant execute on function public.expire_staged_attachments(integer) to service_role;

-- Due objects with no live row, oldest first; one household's when named.
create or replace function public.due_attachment_objects(p_profile_id uuid, p_limit integer)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_limit is null or p_limit < 1 or p_limit > 1000 then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_limit must be 1 to 1000';
  end if;
  return coalesce((
    select jsonb_agg(q.object_path order by q.due_at, q.object_path)
      from (select s.object_path, s.due_at from public.attachment_object_sweep s
             where s.due_at <= now()
               and (p_profile_id is null or s.object_path like p_profile_id::text || '/%')
               and not exists (select 1 from public.household_attachments a where a.object_path = s.object_path)
             order by s.due_at, s.object_path limit p_limit) q), '[]'::jsonb);
end;
$$;

revoke execute on function public.due_attachment_objects(uuid, integer) from public, anon, authenticated;
grant execute on function public.due_attachment_objects(uuid, integer) to service_role;

-- After the Storage API deleted them: drop those entries, never one whose row exists.
create or replace function public.forget_attachment_objects(p_paths text[])
returns integer
language plpgsql
security invoker
set search_path = public
as $$
declare
  removed int;
begin
  if p_paths is null or cardinality(p_paths) > 1000 then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'at most 1000 paths';
  end if;
  delete from public.attachment_object_sweep s
   where s.object_path = any (p_paths)
     and not exists (select 1 from public.household_attachments a where a.object_path = s.object_path);
  get diagnostics removed = row_count;
  return removed;
end;
$$;

revoke execute on function public.forget_attachment_objects(text[]) from public, anon, authenticated;
grant execute on function public.forget_attachment_objects(text[]) to service_role;

-- ---------------------------------------------------------------------------
-- 9. The private bucket
-- ---------------------------------------------------------------------------
-- Supabase's storage schema holds the buckets. Where it is absent (a plain
-- Postgres, the PGlite tests) this block does nothing. The bucket is private:
-- no public URL, and with no storage policy naming it only the service role
-- reaches its objects. Its size and type limits repeat the route's (Ruling A3).

do $$
begin
  if to_regclass('storage.buckets') is not null then
    insert into storage.buckets (id, name, public) values ('household-attachments', 'household-attachments', false)
    on conflict (id) do nothing;
    if exists (select 1 from information_schema.columns
                where table_schema = 'storage' and table_name = 'buckets' and column_name = 'file_size_limit')
       and exists (select 1 from information_schema.columns
                    where table_schema = 'storage' and table_name = 'buckets' and column_name = 'allowed_mime_types') then
      execute $sql$update storage.buckets set file_size_limit = 15728640,
                     allowed_mime_types = array['image/jpeg', 'image/png', 'image/webp']
               where id = 'household-attachments'$sql$;
    end if;
  end if;
end $$;

-- What the verification reads about the bucket, without naming the storage
-- schema in the query itself (it may be absent): {storage, bucket, private,
-- policies}, policies counting storage policies that name the bucket. Where
-- the storage schema exists (Supabase), the verification's bucket_private is
-- true only when the bucket exists and is not public, and no_bucket_policy
-- only when no storage policy names it.
create or replace function public.attachment_storage_state()
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
declare
  has_bucket boolean := false;
  is_private boolean := false;
  policies   int := 0;
begin
  if to_regclass('storage.buckets') is null then
    return jsonb_build_object('storage', false, 'bucket', false, 'private', false, 'policies', 0);
  end if;
  execute $q$select count(*) > 0, coalesce(bool_and(not b.public), false)
               from storage.buckets b where b.id = 'household-attachments'$q$
     into has_bucket, is_private;
  select count(*) into policies from pg_policies
   where schemaname = 'storage' and (coalesce(qual, '') || coalesce(with_check, '')) like '%household-attachments%';
  return jsonb_build_object('storage', true, 'bucket', has_bucket, 'private', is_private, 'policies', policies);
end;
$$;

revoke execute on function public.attachment_storage_state() from public, anon, authenticated;
grant execute on function public.attachment_storage_state() to service_role;

-- ---------------------------------------------------------------------------
-- Verification (read only). Expect one row, all eight columns true.
-- ---------------------------------------------------------------------------
--   select
--     (select bool_and(relrowsecurity) from pg_class
--       where oid in ('public.household_attachments'::regclass, 'public.attachment_object_sweep'::regclass)) as rls_on,
