--                                'public.summary_privacy_counts(uuid)']) as f)
--       as functions_service_role_only,
--     (select count(*) from pg_proc p join pg_namespace n on n.oid = p.pronamespace
--       where n.nspname = 'public' and not p.prosecdef and 'search_path=public' = any (p.proconfig)
--         and p.proname in ('household_summary_json', 'read_household_summaries', 'read_household_summary',
--                           'household_summary_usage', 'commit_household_summary', 'summary_privacy_counts',
