-- ===========================================================================
-- 0032_participation_directory.sql
-- ===========================================================================

-- HALO: the participation directory (B18 plan,
-- docs/backend/plans/b18-participation-directory.md, Rulings P1 to P11).
-- Two tables of PUBLIC reference data that a PERSON writes by hand in the SQL
-- editor: organization participation profiles and dated or rolling
-- opportunities, each keyed to a public.volunteer_orgs row. The API never
-- writes them. Only a row a person has verified is ever served.
--
-- Run once in the Supabase SQL editor, AFTER 0004 (volunteer_orgs). It does
-- not need 0005 to 0031 and may go before or after any of them. Safe to
-- re-run.
--
-- Locks: creates two new tables, their indexes, triggers and functions, which
-- no other statement can be waiting on. Each foreign key to volunteer_orgs
-- takes a brief SHARE ROW EXCLUSIVE on volunteer_orgs as it is created; reads
-- of that table (GET /api/volunteer) are not blocked by it. Nothing existing
-- is read or rewritten.
--
-- WHAT IS SERVED (the three read functions, section 5):
--   * a row only when verified_by and verified_at are set and verified_at is
--     not after the read's clock (Ruling P2);
--   * a search only rows still fresh: an opportunity verified within the last
--     29 days, a profile within 180 days (P2);
--   * an opportunity search only status 'listed', and a scheduled listing only
--     while it has not started (P3). Rolling programs have no dates;
--   * the detail read any verified opportunity, whatever its status or date,
--     so a saved commitment can learn it was cancelled or has passed (P4).
--
-- A VERIFICATION COVERS EXACTLY WHAT IS SERVED (section 4): any change to a
-- served column that does not also set a new verified_at clears verified_by
-- and verified_at, so the row stops being served until a person checks it
-- again. Every change raises revision by one. So recording a cancellation
-- (or full, or postponed) must set verified_at = now() in the same UPDATE, or
-- the detail stops answering for that listing (YOUR_TODO.md 2.23).
--
-- Errors the triggers raise, SQLSTATE P0001 with exactly this message and a
-- DETAIL naming the column (never a value):
--   HALO_INVALID_INPUT   a timezone that is not an IANA zone, or a venue date
--                        that is not the start's date in the venue's zone
-- Every other malformed value is refused by a named CHECK constraint.
--
-- Degrades cleanly: until this is applied the three B18 routes answer the
-- non-retryable 503 feature_unavailable (a missing function is PGRST202 or
-- 42883). They are also behind HALO_FEATURE_PARTICIPATION, off by default.
--
-- Privacy: no household data at all. Nothing here references profiles or
-- auth.users; verified_by is the name or initials of whoever checked a listing
-- and is never served. The service role is the only reader: row level security
-- is on with no policy and the default privileges are revoked.

-- ---------------------------------------------------------------------------
-- 1. Shape checks, immutable, used by the CHECK constraints
-- ---------------------------------------------------------------------------

-- One served sentence: present, bounded, at least one character that is not
-- whitespace as JavaScript's trim() counts it (tab, line breaks, no-break and
-- the other Unicode spaces), no control character, no em dash (AGENTS.md:
-- none in app-facing text), and no <placeholder> left from the YOUR_TODO.md
-- 2.23 template, so the template cannot be run unedited.
create or replace function public.participation_text_ok(p_value text, p_max integer)
returns boolean
language sql
immutable
security invoker
set search_path = public
as $$
  select p_value is not null and char_length(p_value) <= p_max
     and p_value ~ ('[^ ' || chr(9) || chr(10) || chr(13) || chr(160) || chr(5760) || chr(8192) || '-' || chr(8202)
                    || chr(8232) || chr(8233) || chr(8239) || chr(8287) || chr(12288) || chr(65279) || ']')
     and p_value !~ '[\x01-\x08\x0b\x0c\x0e-\x1f]' and strpos(p_value, U&'\2014') = 0
     and p_value !~ '<[^>]*>';
$$;

-- An official https address (the client's safeSourceUrl, made stricter so a
-- row the database accepts is never one the client refuses): a host name of
-- dot-separated labels ending in a letter top-level domain (no IP address, no
-- port, no user name or password), then printable ASCII only (no space, no
-- control character, no em dash; anything else is percent-encoded), at most
-- 2000 characters.
create or replace function public.participation_url_ok(p_value text)
returns boolean
language sql
immutable
security invoker
set search_path = public
as $$
  select p_value is not null and char_length(p_value) <= 2000
     and p_value ~ '^https://([A-Za-z0-9]([A-Za-z0-9-]{0,61}[A-Za-z0-9])?\.)+[A-Za-z]{2,63}([/?#][!-~]*)?$';
$$;

-- A list of short served sentences: 1 to p_items entries, each p_max at most.
create or replace function public.participation_list_ok(p_value text[], p_items integer, p_max integer)
returns boolean
language sql
immutable
security invoker
set search_path = public
as $$
  select p_value is not null and cardinality(p_value) between 1 and p_items
     and array_ndims(p_value) = 1
     and coalesce((select bool_and(public.participation_text_ok(v, p_max)) from unnest(p_value) as v), false);
$$;

-- The areas a listing serves: gazetteer ids exactly as locations.search
-- returns them (lib/places.js), or 'us-state:NC' for the whole state.
create or replace function public.participation_places_ok(p_value text[])
returns boolean
language sql
immutable
security invoker
set search_path = public
as $$
  select p_value is not null and cardinality(p_value) between 1 and 200 and array_ndims(p_value) = 1
     and coalesce((select bool_and(v ~ '^(us-state:NC|us-county:37[0-9]{3}|us-place:37[0-9]{5}|us-zcta:[0-9]{5})$')
                     from unnest(p_value) as v), false);
$$;

-- An organization profile's steps: 1 to 30 objects of exactly {title, text}.
create or replace function public.participation_steps_ok(p_value jsonb)
returns boolean
language sql
immutable
security invoker
set search_path = public
as $$
  select p_value is not null and jsonb_typeof(p_value) = 'array' and jsonb_array_length(p_value) between 1 and 30
     and coalesce((select bool_and(jsonb_typeof(s) = 'object'
                                   and (select array_agg(k order by k) from jsonb_object_keys(s) as k) = array['text', 'title']
                                   and jsonb_typeof(s -> 'title') = 'string' and jsonb_typeof(s -> 'text') = 'string'
                                   and public.participation_text_ok(s ->> 'title', 200)
                                   and public.participation_text_ok(s ->> 'text', 1000))
                     from jsonb_array_elements(p_value) as s), false);
$$;

-- An organization profile's further official pages: 0 to 20 objects of exactly {title, url}.
create or replace function public.participation_sources_ok(p_value jsonb)
returns boolean
language sql
immutable
security invoker
set search_path = public
as $$
  select p_value is not null and jsonb_typeof(p_value) = 'array' and jsonb_array_length(p_value) <= 20
     and coalesce((select bool_and(jsonb_typeof(s) = 'object'
                                   and (select array_agg(k order by k) from jsonb_object_keys(s) as k) = array['title', 'url']
                                   and jsonb_typeof(s -> 'title') = 'string' and jsonb_typeof(s -> 'url') = 'string'
                                   and public.participation_text_ok(s ->> 'title', 200)
                                   and public.participation_url_ok(s ->> 'url'))
                     from jsonb_array_elements(p_value) as s), true);
$$;

-- ---------------------------------------------------------------------------
-- 2. Organization participation profiles (organizations.search)
-- ---------------------------------------------------------------------------
-- One participation route of one organization (Ruling P10). Every column
-- below verified_by is the client's LocalParticipationResource field of the
-- same meaning (lib/frontend/explore-local-resources.ts:3-11).

create table if not exists public.participation_profiles (
  -- Lowercase slug, the served id.
  id               text        primary key,
  -- The organization this route belongs to.
  org_id           uuid        not null references public.volunteer_orgs (id) on delete restrict,
  title            text        not null,
  organizer        text        not null,
  interest         text        not null,
  -- The served area in words; matching uses served_place_ids only.
  area             text        not null,
  served_place_ids text[]      not null,
  mission          text        not null,
  work             text        not null,
  url              text        not null,
  source_title     text        not null,
  extra_sources    jsonb       not null default '[]'::jsonb,
  -- An address the organization publishes, what kind it is (never served) and
  -- a sentence saying so (served as addressRole): all three or none.
  address          text,
  address_kind     text,
  address_role     text,
  contact          text,
  effort           text        not null,
  age              text        not null,
  cost             text        not null,
  access           text        not null,
  steps            jsonb       not null,
  bring            text        not null,
  followup         text        not null,
  -- Who checked this listing against its official page, and when. Both or neither.
  verified_by      text,
  verified_at      timestamptz,
  revision         integer     not null default 1,
  created_at       timestamptz not null default now(),
  updated_at       timestamptz not null default now(),
  constraint participation_profiles_id_check check (id ~ '^[a-z0-9][a-z0-9-]{0,79}$'),
  constraint participation_profiles_interest_check
    check (interest in ('Cleanup', 'Trees & habitat', 'Gardening', 'Community learning')),
  constraint participation_profiles_text_check
    check (public.participation_text_ok(title, 200) and public.participation_text_ok(organizer, 200)
           and public.participation_text_ok(area, 300) and public.participation_text_ok(mission, 2000)
           and public.participation_text_ok(work, 2000) and public.participation_text_ok(source_title, 200)
           and public.participation_text_ok(effort, 1000) and public.participation_text_ok(age, 500)
           and public.participation_text_ok(cost, 500) and public.participation_text_ok(access, 1000)
           and public.participation_text_ok(bring, 1000) and public.participation_text_ok(followup, 1000)),
  constraint participation_profiles_links_check
    check (public.participation_url_ok(url) and public.participation_sources_ok(extra_sources)
           and public.participation_steps_ok(steps) and public.participation_places_ok(served_place_ids)),
  constraint participation_profiles_address_check
    check ((address is null and address_kind is null and address_role is null)
           or (public.participation_text_ok(address, 300) and address_kind in ('office', 'mailing', 'meeting', 'service-area')
               and public.participation_text_ok(address_role, 500))),
  constraint participation_profiles_contact_check check (contact is null or public.participation_text_ok(contact, 300)),
  constraint participation_profiles_verified_check
    check ((verified_by is null) = (verified_at is null)
           and (verified_by is null or public.participation_text_ok(verified_by, 120))),
  constraint participation_profiles_revision_check check (revision >= 1)
);

create index if not exists participation_profiles_org_idx on public.participation_profiles (org_id);

-- ---------------------------------------------------------------------------
-- 3. Dated and rolling opportunities (opportunities.search, opportunities.detail)
-- ---------------------------------------------------------------------------
-- Every column below verified_by is the client's CommunityOpportunity field
-- of the same meaning (lib/frontend/explore-opportunities.ts:6-15), except
-- meeting_address (served as `address`) and join_text (served as `join`).
-- There is deliberately no capacity, distance or availability column: a
-- listing is `full` only when the organizer says so, through status.

create table if not exists public.participation_opportunities (
  id                    text        primary key,
  org_id                uuid        not null references public.volunteer_orgs (id) on delete restrict,
  organizer             text        not null,
  title                 text        not null,
  interest              text        not null,
  -- An illustration of the activity, never a picture of the venue.
  artwork               text        not null,
  kind                  text        not null,
  -- Scheduled: both, with their zone, end after start. Rolling: neither.
  starts_at             timestamptz,
  ends_at               timestamptz,
  -- The time as a person reads it on the listing, venue local.
  time_label            text        not null,
  -- Optional venue date and IANA zone; basis 'source' when the listing states the zone.
  venue_local_date      date,
  venue_timezone        text,
  venue_timezone_basis  text,
  status                text        not null default 'listed',
  area                  text        not null,
  served_place_ids      text[]      not null,
  -- The meeting place, and optionally its address. Never an office or mailing address.
  venue                 text        not null,
  meeting_address       text,
  url                   text        not null,
  summary               text        not null,
  work                  text[]      not null,
  duration              text        not null,
  cost                  text        not null,
  age                   text        not null,
  access                text        not null,
  bring                 text        not null,
  -- The official next step.
  join_text             text        not null,
  safety                text        not null,
  verified_by           text,
  verified_at           timestamptz,
  revision              integer     not null default 1,
  created_at            timestamptz not null default now(),
  updated_at            timestamptz not null default now(),
  constraint participation_opportunities_id_check check (id ~ '^[a-z0-9][a-z0-9-]{0,79}$'),
  constraint participation_opportunities_choice_check
    check (interest in ('Cleanup', 'Trees & habitat', 'Gardening', 'Community learning')
           and artwork in ('tree', 'cleanup', 'garden')
           and status in ('listed', 'cancelled', 'full', 'postponed')),
  constraint participation_opportunities_kind_check
    -- Whole minutes, before the year 9999: the served instants are whole
    -- seconds with a four-digit year, and the client needs end after start.
    check ((kind = 'scheduled' and starts_at is not null and ends_at is not null and ends_at > starts_at
            and mod(extract(epoch from starts_at), 60) = 0 and mod(extract(epoch from ends_at), 60) = 0
            and ends_at < timestamptz '9999-01-01 00:00:00+00')
           or (kind = 'rolling' and starts_at is null and ends_at is null and venue_local_date is null)),
  constraint participation_opportunities_zone_check
    check ((venue_timezone_basis is null or (venue_timezone_basis in ('source', 'inferred') and venue_timezone is not null))
           and (venue_timezone is null or char_length(venue_timezone) <= 100)),
  constraint participation_opportunities_text_check
    check (public.participation_text_ok(organizer, 200) and public.participation_text_ok(title, 200)
           and public.participation_text_ok(time_label, 200) and public.participation_text_ok(area, 300)
           and public.participation_text_ok(venue, 300) and public.participation_text_ok(summary, 2000)
           and public.participation_text_ok(duration, 200) and public.participation_text_ok(cost, 500)
           and public.participation_text_ok(age, 500) and public.participation_text_ok(access, 1000)
           and public.participation_text_ok(bring, 1000) and public.participation_text_ok(join_text, 1000)
           and public.participation_text_ok(safety, 1000)
           and (meeting_address is null or public.participation_text_ok(meeting_address, 300))),
  constraint participation_opportunities_links_check
    check (public.participation_url_ok(url) and public.participation_list_ok(work, 20, 500)
           and public.participation_places_ok(served_place_ids)),
  constraint participation_opportunities_verified_check
    check ((verified_by is null) = (verified_at is null)
           and (verified_by is null or public.participation_text_ok(verified_by, 120))),
  constraint participation_opportunities_revision_check check (revision >= 1)
);

create index if not exists participation_opportunities_org_idx on public.participation_opportunities (org_id);

alter table public.participation_profiles enable row level security;
alter table public.participation_opportunities enable row level security;
-- No policy at all: the browser roles can do nothing, the service role reads.
revoke all on table public.participation_profiles from anon, authenticated;
revoke all on table public.participation_opportunities from anon, authenticated;

-- ---------------------------------------------------------------------------
-- 4. The guards: revision, verification and the venue zone
-- ---------------------------------------------------------------------------

-- BEFORE UPDATE on both tables. A change to anything served (every column but
-- the bookkeeping ones) without a new verified_at clears the verification.
create or replace function public.participation_listing_guard()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
declare
  v_meta constant text[] := array['revision', 'created_at', 'updated_at', 'verified_by', 'verified_at'];
begin
  if (to_jsonb(new) - v_meta) is distinct from (to_jsonb(old) - v_meta)
     and new.verified_at is not distinct from old.verified_at then
    new.verified_by := null;
    new.verified_at := null;
  end if;
  new.revision := old.revision + 1;
  new.updated_at := now();
  new.created_at := old.created_at;
  return new;
end;
$$;

revoke execute on function public.participation_listing_guard() from public, anon, authenticated;

drop trigger if exists participation_profiles_guard on public.participation_profiles;
create trigger participation_profiles_guard
  before update on public.participation_profiles
  for each row execute function public.participation_listing_guard();

drop trigger if exists participation_opportunities_guard on public.participation_opportunities;
create trigger participation_opportunities_guard
  before update on public.participation_opportunities
  for each row execute function public.participation_listing_guard();

-- BEFORE INSERT OR UPDATE on opportunities: the zone is an IANA name the
-- database knows, and a stated venue date is the start's date in that zone
-- (the client rejects a listing where they disagree, explore-service.ts:53).
create or replace function public.participation_opportunity_zone_check()
returns trigger
language plpgsql
security invoker
set search_path = public
as $$
begin
  if new.venue_timezone is not null
     and (new.venue_timezone !~ '^([A-Za-z]+(/[A-Za-z0-9_+-]+)+|UTC)$'
          or not exists (select 1 from pg_catalog.pg_timezone_names where name = new.venue_timezone)) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'venue_timezone is not an IANA zone';
  end if;
  if new.kind = 'scheduled' and new.venue_timezone_basis = 'source' and new.venue_local_date is not null
     and (new.starts_at at time zone new.venue_timezone)::date <> new.venue_local_date then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'venue_local_date is not the start date in venue_timezone';
  end if;
  return new;
end;
$$;

revoke execute on function public.participation_opportunity_zone_check() from public, anon, authenticated;

drop trigger if exists participation_opportunities_zone on public.participation_opportunities;
create trigger participation_opportunities_zone
  before insert or update on public.participation_opportunities
  for each row execute function public.participation_opportunity_zone_check();

-- ---------------------------------------------------------------------------
-- 5. The reads (service role only)
-- ---------------------------------------------------------------------------
-- p_now is the route's clock; p_place_ids the area's own id, its county and
-- 'us-state:NC' (Ruling P5). Instants are formatted in UTC explicitly, so the
-- session's TimeZone never changes an answer. Each read returns at most 1000.

-- One opportunity as the client's CommunityOpportunity, plus revision.
create or replace function public.participation_opportunity_json(o public.participation_opportunities)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', o.id, 'organizer', o.organizer, 'title', o.title, 'interest', o.interest, 'artwork', o.artwork,
    'scopes', '[]'::jsonb, 'area', o.area, 'venue', o.venue, 'address', o.meeting_address, 'kind', o.kind,
    'startsAt', to_char(o.starts_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'endsAt', to_char(o.ends_at at time zone 'UTC', 'YYYY-MM-DD"T"HH24:MI:SS"Z"'),
    'timeLabel', o.time_label, 'venueLocalDate', to_char(o.venue_local_date, 'YYYY-MM-DD'),
    'venueTimezone', o.venue_timezone, 'venueTimezoneBasis', o.venue_timezone_basis,
    'checkedAt', to_char(o.verified_at at time zone 'UTC', 'YYYY-MM-DD'), 'status', o.status, 'url', o.url,
    'summary', o.summary, 'work', to_jsonb(o.work), 'duration', o.duration, 'cost', o.cost, 'age', o.age,
    'access', o.access, 'bring', o.bring, 'join', o.join_text, 'safety', o.safety, 'revision', o.revision));
$$;

revoke execute on function public.participation_opportunity_json(public.participation_opportunities) from public, anon, authenticated;
grant execute on function public.participation_opportunity_json(public.participation_opportunities) to service_role;

-- The servable opportunities for an area (Rulings P2, P3): verified, fresh,
-- listed, not started; scheduled soonest first, then rolling by title.
create or replace function public.read_participation_opportunities(p_place_ids text[], p_now timestamptz)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_now is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_now is required';
  end if;
  return coalesce((
    select jsonb_agg(public.participation_opportunity_json(o) order by (o.kind = 'rolling'), o.starts_at, o.title, o.id)
      from public.participation_opportunities o
     where o.id in (
       select c.id
         from public.participation_opportunities c
        where c.verified_at is not null and c.verified_by is not null
          and c.verified_at <= p_now
          and (date_trunc('day', c.verified_at at time zone 'UTC') at time zone 'UTC') >= p_now - interval '29 days'
          and c.status = 'listed'
          and (c.kind = 'rolling' or c.starts_at > p_now)
          and c.served_place_ids && coalesce(p_place_ids, '{}'::text[])
        order by (c.kind = 'rolling'), c.starts_at, c.title, c.id
        limit 1000)), '[]'::jsonb);
end;
$$;

revoke execute on function public.read_participation_opportunities(text[], timestamptz) from public, anon, authenticated;
grant execute on function public.read_participation_opportunities(text[], timestamptz) to service_role;

-- One verified opportunity by id, whatever its status, date or freshness
-- (Ruling P4); null when there is none or it is not verified.
create or replace function public.read_participation_opportunity(p_id text, p_now timestamptz)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_now is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_now is required';
  end if;
  return (select public.participation_opportunity_json(o)
            from public.participation_opportunities o
           where o.id = p_id and o.verified_at is not null and o.verified_by is not null and o.verified_at <= p_now);
end;
$$;

revoke execute on function public.read_participation_opportunity(text, timestamptz) from public, anon, authenticated;
grant execute on function public.read_participation_opportunity(text, timestamptz) to service_role;

-- One profile as the client's LocalParticipationResource with checkedAt, plus revision.
create or replace function public.participation_profile_json(p public.participation_profiles)
returns jsonb
language sql
stable
security invoker
set search_path = public
as $$
  select jsonb_strip_nulls(jsonb_build_object(
    'id', p.id, 'title', p.title, 'organizer', p.organizer, 'interest', p.interest, 'scopes', '[]'::jsonb,
    'area', p.area, 'mission', p.mission, 'work', p.work, 'url', p.url, 'sourceTitle', p.source_title,
    'extraSources', case when jsonb_array_length(p.extra_sources) > 0 then p.extra_sources end,
    'address', p.address, 'addressRole', p.address_role, 'contact', p.contact,
    'effort', p.effort, 'age', p.age, 'cost', p.cost, 'access', p.access, 'steps', p.steps,
    'bring', p.bring, 'followup', p.followup,
    'checkedAt', to_char(p.verified_at at time zone 'UTC', 'YYYY-MM-DD'), 'revision', p.revision));
$$;

revoke execute on function public.participation_profile_json(public.participation_profiles) from public, anon, authenticated;
grant execute on function public.participation_profile_json(public.participation_profiles) to service_role;

-- The servable profiles for an area (Ruling P2): verified within 180 days, by title.
create or replace function public.read_participation_profiles(p_place_ids text[], p_now timestamptz)
returns jsonb
language plpgsql
stable
security invoker
set search_path = public
as $$
begin
  if p_now is null then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001', detail = 'p_now is required';
  end if;
  return coalesce((
    select jsonb_agg(public.participation_profile_json(p) order by p.title, p.id)
      from public.participation_profiles p
     where p.id in (
       select c.id
         from public.participation_profiles c
        where c.verified_at is not null and c.verified_by is not null
          and c.verified_at <= p_now
          and (date_trunc('day', c.verified_at at time zone 'UTC') at time zone 'UTC') >= p_now - interval '180 days'
          and c.served_place_ids && coalesce(p_place_ids, '{}'::text[])
        order by c.title, c.id
        limit 1000)), '[]'::jsonb);
end;
$$;

revoke execute on function public.read_participation_profiles(text[], timestamptz) from public, anon, authenticated;
grant execute on function public.read_participation_profiles(text[], timestamptz) to service_role;

-- The shape checks are called by the CHECK constraints, so whoever writes a
-- row runs them: the SQL editor's role, and the service role (which no route
-- uses to write here). The browser roles never can.
revoke execute on function public.participation_text_ok(text, integer) from public, anon, authenticated;
revoke execute on function public.participation_url_ok(text) from public, anon, authenticated;
revoke execute on function public.participation_list_ok(text[], integer, integer) from public, anon, authenticated;
revoke execute on function public.participation_places_ok(text[]) from public, anon, authenticated;
revoke execute on function public.participation_steps_ok(jsonb) from public, anon, authenticated;
revoke execute on function public.participation_sources_ok(jsonb) from public, anon, authenticated;
grant execute on function public.participation_text_ok(text, integer) to service_role;
grant execute on function public.participation_url_ok(text) to service_role;
grant execute on function public.participation_list_ok(text[], integer, integer) to service_role;
grant execute on function public.participation_places_ok(text[]) to service_role;
grant execute on function public.participation_steps_ok(jsonb) to service_role;
grant execute on function public.participation_sources_ok(jsonb) to service_role;

